insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-2b147d92aac4', 'en', 'A1', 'Have and Has', 'Hello! Today we learn about ''have'' and ''has''. We use these words to show possession. For example: ''I have a car.'' You have a house. Carlos has a bike. ''Have'' is for I, you, we, they. ''Has'' is for he, she, it. Look at the examples: I have a phone. You have a book. We have a cat. They have a dog. He has a brother. She has a friend. It has a tail. Remember, ''has'' is for one person or thing like ''he'', ''she'', ''it''. ''Have'' is for more than one or for ''I'' and ''you''. Practice with these sentences: ''Ana has a sister.'' ''I have a bag.''', 'Choose the correct word: ''Maria ______ a new iPhone.''', '["have","has","haves","having"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"Maria é ''she'', então usamos ''has''.","options":["have","has","haves","having"],"prompt":"Choose the correct word: ''Maria ______ a new iPhone.''"},{"answer_index":2,"explanation_pt_br":"Para ''they'', usamos ''have''. As outras opções estão incorretas.","options":["I has a brother.","You has a car.","They have a house.","She have a dog."],"prompt":"Choose the correct sentence:"}]'::jsonb, 0, true)
