insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-10a95db9f2e9', 'en', 'A1', 'A Cat and the Cats: Singular and Plural', 'Look at a cat. It is one cat. Now look at two cats. We say "cats". For most nouns, add -s for plural: book → books, pen → pens. For nouns ending in -s, -ss, -x, -ch, or -sh, add -es: bus → buses, box → boxes, watch → watches, dish → dishes. Some nouns change: man → men, woman → women, child → children. Use "a" or "an" for singular. Use "the" for specific nouns. For plurals, we don''t use "a" or "an". We can use "the" for specific plurals: the cats. Let''s practice!', 'Which word is plural?', '["cat","cats","book","pen"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"A palavra ''cats'' tem o ''s'' no final, indicando plural (gatos). As outras opções estão no singular.","options":["cat","cats","book","pen"],"prompt":"Which word is plural?"},{"answer_index":1,"explanation_pt_br":"Para palavras terminadas em ''x'', adicionamos ''es'' para formar o plural: box -> boxes (caixas).","options":["boxs","boxes","box","boxies"],"prompt":"What is the plural of ''box''?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-e2002a823c67', 'en', 'A1', 'There is / There are', 'In English, we use ''there is'' for one thing and ''there are'' for two or more things. For example: ''There is a book on the table.'' ''There are two books on the table.'' This helps us say what exists or is present.

Look at your room. What do you see? Maybe there is a bed, a desk, and a chair. There are also some clothes on the floor. Use ''there is'' for singular and ''there are'' for plural. Remember: ''there is'' = ''there''s'' (short form).', 'Choose the correct sentence.', '["There is two cats in the garden.","There are two cats in the garden.","There are a cat in the garden.","There is a cats in the garden."]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"Usamos ''there are'' para mais de uma coisa. ''Two cats'' é plural, então ''there are'' está correto.","options":["There is two cats in the garden.","There are two cats in the garden.","There are a cat in the garden.","There is a cats in the garden."],"prompt":"Choose the correct sentence."},{"answer_index":1,"explanation_pt_br":"Usamos ''there is'' para uma coisa singular. ''A supermarket'' é singular, então ''there is'' está correto.","options":["There are","There is","There","Are there"],"prompt":"Complete the sentence: ''____ a supermarket near my house.''"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-e4042d51744c', 'en', 'A1', 'Can You Help Me?', 'Hello! Today we learn about ''can''. ''Can'' is a special word. We use ''can'' to say something is possible. We also use ''can'' to ask for permission. For example, "I can swim" means I know how to swim. "Can I go to the bathroom?" means I ask for permission.

Here are some words you will see: help, open, close, use, play, go, come, sit. Now, let''s read a small story.

Maria is at a restaurant. She is hungry. She sees a waiter. She says, "Can I have a menu, please?" The waiter says, "Yes, of course." Maria looks at the menu. She wants pasta. She asks, "Can I order pasta?" The waiter says, "Sure." After eating, Maria wants to pay. She asks, "Can I pay by card?" The waiter says, "Yes, you can." Maria is happy.', 'What does Maria say when she wants the menu?', '["Can I have a menu, please?","I can eat pasta.","Can you help me?","I want to pay."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Maria pede o cardápio dizendo ''Can I have a menu, please?'' Isso é um pedido de permissão.","options":["Can I have a menu, please?","I can eat pasta.","Can you help me?","I want to pay."],"prompt":"What does Maria say when she wants the menu?"},{"answer_index":1,"explanation_pt_br":"O garçom diz ''Yes, you can.'' Portanto, ela pode pagar com cartão.","options":["No, she can''t.","Yes, she can.","Maybe.","I don''t know."],"prompt":"Can Maria pay by card?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-c9bc9d285fb8', 'en', 'A1', 'Asking Questions in English', 'Hello! Today we learn about questions. In English, we ask questions with words like ''what'', ''where'', ''when'', ''who'', and ''why''. For example, ''What is your name?'' or ''Where do you live?''. These are WH-questions. We also ask yes/no questions. For yes/no questions, we start with ''do'', ''does'', ''is'', or ''are''. For example, ''Do you like coffee?'' or ''Are you a student?''. For WH-questions, we put the WH-word first. For example, ''Where are you from?''. Answering is easy. For yes/no questions, say ''Yes, I do.'' or ''No, I don''t.'' For WH-questions, give information. For example, ''I am from Brazil.'' Practice with your friends. Ask questions and answer. It is fun!', 'Which question is a yes/no question?', '["What is your name?","Where do you live?","Do you like pizza?","Why are you happy?"]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"A pergunta ''Do you like pizza?'' começa com ''Do'' e espera uma resposta sim ou não.","options":["What is your name?","Where do you live?","Do you like pizza?","Why are you happy?"],"prompt":"Which question is a yes/no question?"},{"answer_index":2,"explanation_pt_br":"''Where'' significa ''onde'', então a pergunta ''Where do you work?'' pergunta sobre um lugar.","options":["Who is your teacher?","When is your birthday?","Where do you work?","Why do you study?"],"prompt":"Which question asks about a place?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-dc4173aeb8a0', 'en', 'A1', 'Where Is It?', 'Hello! Today we learn about prepositions: in, on, under, next to, and behind. These words help us say where things are.

Look at the picture. The cat is in the box. The book is on the table. The ball is under the chair. The dog is next to the car. The boy is behind the door.

In class, you can say: "My phone is in my bag." "The teacher is next to the board." "The keys are on the desk." Prepositions are very useful. They help you describe your room, your house, and your city.

Remember: ''in'' for inside, ''on'' for on top, ''under'' for below, ''next to'' for beside, and ''behind'' for at the back. Practice with your things!', 'Where is the cat? The cat is ___ the box.', '["in","on","under","next to"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"''In'' é usado para indicar que algo está dentro de um espaço fechado, como uma caixa.","options":["in","on","under","next to"],"prompt":"Where is the cat? The cat is ___ the box."},{"answer_index":1,"explanation_pt_br":"''Under'' significa ''embaixo de''. A bola está embaixo da cadeira.","options":["on","under","behind","next to"],"prompt":"Where is the ball? The ball is ___ the chair."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-c61ac521cbe4', 'en', 'A1', 'Pronouns with ''to be''', 'In English, we use pronouns to talk about people and things. The pronouns are: I, you, he, she, it, we, they. We use the verb ''to be'' with these pronouns. For example: I am Ana. You are my friend. He is a teacher. We use ''am'' with ''I''. We use ''is'' with ''he'', ''she'', and ''it''. We use ''are'' with ''you'', ''we'', and ''they''. For example: She is happy. They are students.

Let''s practice! I am from Brazil. You are in a class. He is your brother. She is a doctor. It is a cat. We are friends. They are from São Paulo. Remember: ''I'' is always with ''am''. ''You'' is always with ''are''. ''He'', ''she'', ''it'' are with ''is''. ''We'' and ''they'' are with ''are''. This is very important!

Now, answer these questions:', 'Which pronoun do we use with ''am''?', '["I","you","he","they"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"O pronome ''I'' sempre usa ''am''. Por exemplo, ''I am a student.''","options":["I","you","he","they"],"prompt":"Which pronoun do we use with ''am''?"},{"answer_index":2,"explanation_pt_br":"A forma correta com ''they'' é ''are''. As outras opções têm erros comuns.","options":["She are a teacher.","We is friends.","They are students.","He am a doctor."],"prompt":"Which sentence is correct?"}]'::jsonb, 0, true)
