insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-8c2c006e3955', 'en', 'A1', 'Things I Have', 'Hello! Today we talk about things we have. I have a car. You have a book. We use "have" for things we own. For example: "I have a phone." "She has a cat." For he, she, it, we use "has". For I, you, we, they, we use "have". Look: "They have a house." "He has a bike." This is easy! Now, think about your things. Do you have a pen? Do you have a friend? Yes! You have many things. Let''s practice with two questions.', 'Which sentence is correct?', '["I has a car.","She have a car.","He has a car.","They has a car."]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"Para ''he'', ''she'', ''it'', usamos ''has''. Então, ''He has a car'' está correto.","options":["I has a car.","She have a car.","He has a car.","They has a car."],"prompt":"Which sentence is correct?"},{"answer_index":1,"explanation_pt_br":"Para ''we'', usamos ''have''. A forma correta é ''We have a big house''.","options":["has","have","haves","is"],"prompt":"Complete: We ___ a big house."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-9df5621a2fde', 'en', 'A1', 'This and That: My Things', 'Hi! Today we learn about things near and far. Use ''this'' for one thing near you. Use ''that'' for one thing far from you. Use ''these'' for many things near you. Use ''those'' for many things far from you.

I have a book in my hand. I say, "This book is good." You see a book on the table far from you. You say, "That book is good." For two books near you, say, "These books are good." For two books far, say, "Those books are good."

Now, let''s practice with my things. This is my phone. That is your phone. These are my keys. Those are your keys. Remember: ''my'' for me, ''your'' for you.', 'You are holding a pen. It is right here in your hand. What do you say?', '["This pen is mine.","That pen is mine.","These pens are mine.","Those pens are mine."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Usamos ''this'' para algo perto de nós, no singular. Como a caneta está na sua mão, é perto, então ''this pen''.","options":["This pen is mine.","That pen is mine.","These pens are mine.","Those pens are mine."],"prompt":"You are holding a pen. It is right here in your hand. What do you say?"},{"answer_index":3,"explanation_pt_br":"Os livros estão longe de você, e são muitos, então usamos ''those'' (plural) e ''books''.","options":["This book is good.","That book is good.","These books are good.","Those books are good."],"prompt":"There are many books on the shelf across the room. What do you say?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-9567e258953f', 'en', 'A1', 'What''s in Your Room?', 'Hello! Today we learn ''there is'' and ''there are''. We use ''there is'' for one thing. We use ''there are'' for two or more things. Look at my room. There is a bed, a desk, and a lamp. There are books on the desk. There are two chairs. There is a window. The room is small but nice. In your room, there is a bed? There are pictures? Let''s see. 

In my kitchen, there is a table. There are four chairs. There is a fridge. There are apples in the fridge. There is a stove. There are cups and plates. In my bathroom, there is a shower. There is a mirror. There are towels. There is soap. Every room has things. We use ''there is'' for one, ''there are'' for many. It is easy!', 'What is in the room?', '["There is a bed.","There are a bed.","There is a books.","There are a lamp."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Usamos ''there is'' para uma coisa singular. ''A bed'' é singular, então ''there is a bed'' está correto.","options":["There is a bed.","There are a bed.","There is a books.","There are a lamp."],"prompt":"What is in the room?"},{"answer_index":2,"explanation_pt_br":"O texto diz ''In my kitchen, there is a table. There are four chairs.'' Portanto, há quatro cadeiras.","options":["There is one chair.","There are two chairs.","There are four chairs.","There are no chairs."],"prompt":"How many chairs are there in the kitchen?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-200bdf42529a', 'en', 'A1', 'Can I Ask?', 'Hello! Today we learn about ''can''. ''Can'' is a special word in English. We use ''can'' to talk about ability and permission. Ability means you know how to do something. Permission means someone says yes to you.

For example, you can say: "I can swim." This means you know how to swim. You can also say: "Can I use your phone?" This is a polite way to ask for something. When we answer, we say "Yes, you can" or "No, you can''t."

Remember: ''can'' does not change. It is the same for ''I'', ''you'', ''he'', ''she'', ''it'', ''we'', and ''they''. After ''can'', we use the base form of the verb. For example, "She can cook." Not "She can cooks."', 'What does ''can'' express?', '["Ability and permission","Past events","Colors and numbers","Food and drinks"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"''Can'' é usado para falar de habilidade (saber fazer algo) e permissão (pedir ou dar autorização).","options":["Ability and permission","Past events","Colors and numbers","Food and drinks"],"prompt":"What does ''can'' express?"},{"answer_index":1,"explanation_pt_br":"Depois de ''can'', usamos o verbo na forma base, sem ''s'' ou ''ing''. Portanto, ''He can sing'' é a forma correta.","options":["He can sings.","He can sing.","He cans sing.","He can singing."],"prompt":"Which sentence is correct?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-fe29ffd19da6', 'en', 'A1', 'Giving Simple Commands', 'In English, we use the imperative to give commands, instructions, or advice. The imperative is the base form of the verb. For example, for the verb "to listen," we say "Listen!" For "to open," we say "Open the door." We use the imperative with "please" to be polite: "Please sit down." We also use negative imperatives with "don''t": "Don''t run!" Imperatives are very common in everyday life, like when we give directions or ask someone to do something.', 'What is the imperative form of the verb "to listen"?', '["Listen","Listens","Listening","Listened"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"O imperativo usa a forma base do verbo, sem sujeito. Então, ''listen'' é a forma correta.","options":["Listen","Listens","Listening","Listened"],"prompt":"What is the imperative form of the verb \"to listen\"?"},{"answer_index":0,"explanation_pt_br":"O imperativo negativo é formado com ''don''t'' + verbo base. ''Don''t run!'' é um comando negativo.","options":["Don''t run!","You run.","Running is fun.","He runs fast."],"prompt":"Which sentence is a negative imperative?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-5e9618defd50', 'en', 'A1', 'At, On, In: Places and Time', 'Hello! Today we learn about prepositions: at, on, in. These words show where or when.

Use ''in'' for big places like cities or countries. Example: I am in Brazil. Use ''on'' for surfaces or streets. Example: The book is on the table. Use ''at'' for a specific point or place. Example: She is at the bus stop.

We also use these words for time. Use ''in'' for months and years: My birthday is in May. Use ''on'' for days and dates: We have class on Monday. Use ''at'' for clock times: The class starts at 9 o''clock.

Now you practice. Read the questions and choose the best answer.', 'Choose the correct preposition: The cat is _______ the box.', '["in","on","at","under"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Usamos ''in'' para indicar que algo está dentro de um espaço fechado, como uma caixa.","options":["in","on","at","under"],"prompt":"Choose the correct preposition: The cat is _______ the box."},{"answer_index":2,"explanation_pt_br":"Usamos ''at'' para horários exatos, como 10:30.","options":["in","on","at","to"],"prompt":"Choose the correct preposition: I have an appointment _______ 10:30."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-f83ea83b4d25', 'en', 'A1', 'I am, You are, We are: Using ''be'' with Pronouns', 'Hello! Today we learn about the verb ''be'' with subject pronouns. Subject pronouns are words like I, you, he, she, it, we, they. We use them to talk about people and things.

For example: I am a teacher. You are a student. She is from Brazil. We are happy. They are friends.

Remember: I am, you are, he/she/it is, we are, they are. Use ''am'' with I, ''is'' with he/she/it, and ''are'' with you, we, they.

Now, look at the pictures and answer the questions.', 'Choose the correct pronoun: ''___ are from Brazil.'' (You and your friend)', '["I","He","We","They"]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"Usamos ''we'' para falar de ''eu e outra pessoa'' (you and your friend). ''They'' é para outras pessoas, não incluindo você.","options":["I","He","We","They"],"prompt":"Choose the correct pronoun: ''___ are from Brazil.'' (You and your friend)"},{"answer_index":1,"explanation_pt_br":"Para ''she'' (ela), usamos ''is''. ''Am'' é só para ''I'', e ''are'' para you, we, they.","options":["am","is","are","be"],"prompt":"Choose the correct form of ''be'': ''She ___ a doctor.''"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-e93b60422ced', 'en', 'A1', 'What Do You Have?', 'Hello! Today we learn about things we have. Look at these examples: I have a book. You have a pen. She has a car. He has a house. We use "have" and "has" to talk about things we own or have. For example: I have a phone. My friend has a dog. We also use "have" for family and friends. I have a brother. She has a sister. When we ask questions, we say: Do you have a...? Does he have a...? For example: Do you have a car? Yes, I do. Does she have a cat? No, she doesn''t. Let''s practice with two questions. Good luck!', 'What do you have?', '["I have a sister.","I have a car.","I have a book.","I have a pen."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"A resposta correta é ''I have a sister.'' porque a pergunta ''What do you have?'' pede algo que você possui, e ''a sister'' (uma irmã) é um exemplo de posse.","options":["I have a sister.","I have a car.","I have a book.","I have a pen."],"prompt":"What do you have?"},{"answer_index":0,"explanation_pt_br":"A forma correta para afirmar com ''she'' é ''she has''. A resposta correta é ''Yes, she has a bike.'' porque usamos ''has'' com ''she''.","options":["Yes, she has a bike.","Yes, she have a bike.","Yes, she has a car.","No, she have a bike."],"prompt":"Does she have a bike?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-d3bf383c1324', 'en', 'A1', 'My Things and This That', 'Hello! Today we learn about possessions and demonstratives. These words help you talk about things you have and things near you.

For example: This is my phone. That is your book. These are my keys. Those are your shoes. We use ''my'' for things I have, ''your'' for things you have. We use ''this'' for one thing near, ''that'' for one thing far. ''These'' and ''those'' are for more than one.

Remember: ''This'' and ''that'' are for one. ''These'' and ''those'' are for two or more. Practice with things around you!', 'What do you say for one thing near you?', '["This","That","These","Those"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Usamos ''this'' para uma coisa perto de nós. ''That'' é para longe, ''these'' e ''those'' são para plural.","options":["This","That","These","Those"],"prompt":"What do you say for one thing near you?"},{"answer_index":0,"explanation_pt_br":"Possessivo de ''I'' é ''my'' (meu/minha). ''Your'' é de ''you'', ''his'' de ''he'', ''her'' de ''she''.","options":["my","your","his","her"],"prompt":"What is the possessive for ''I''?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-0b94a268c685', 'en', 'A1', 'There is / There are', 'In English, we use ''there is'' and ''there are'' to say that something exists. We use ''there is'' for one thing (singular). We use ''there are'' for two or more things (plural).

For example: ''There is a book on the table.'' (one book). ''There are two books on the table.'' (two books). We also use ''there is'' for uncountable nouns, like water or money.

Remember: ''There is'' is often shortened to ''There''s''. For negative, we say ''There isn''t'' (is not) or ''There aren''t'' (are not). For questions, we say ''Is there...?'' or ''Are there...?''.', 'Which sentence is correct?', '["There is two chairs in the room.","There are two chairs in the room.","There are a chair in the room.","There is two chair in the room."]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"Usamos ''there are'' para plural (duas cadeiras).","options":["There is two chairs in the room.","There are two chairs in the room.","There are a chair in the room.","There is two chair in the room."],"prompt":"Which sentence is correct?"},{"answer_index":0,"explanation_pt_br":"Para perguntar sobre uma coisa no singular, usamos ''Is there...''.","options":["Is","Are","Am","Do"],"prompt":"Complete the question: ______ there a supermarket near here?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-b7e06a6492a9', 'en', 'A1', 'I Can Do It!', 'Hello! Today we learn about ''can''. We use ''can'' for ability and permission. For ability, we say: ''I can swim.'' For permission, we say: ''Can I go to the bathroom?'' The word ''can'' is the same for all people: I can, you can, he can, she can, we can, they can. We do not add ''s'' for he/she. For questions, we put ''can'' first: ''Can you help me?'' For negatives, we use ''cannot'' or ''can''t'': ''I can''t drive.'' Remember: after ''can'', we use the base verb, without ''to''. For example: ''She can sing.'' Not ''She can to sing.'' Practice with these examples: ''He can play the guitar.'' ''Can I open the window?'' ''They can''t speak French.'' Now you are ready for the questions!', 'What is the correct sentence?', '["I can to swim.","I can swim.","I cans swim.","I can swimming."]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"Depois de ''can'', usamos o verbo na forma base, sem ''to''. Portanto, ''I can swim.'' está correto.","options":["I can to swim.","I can swim.","I cans swim.","I can swimming."],"prompt":"What is the correct sentence?"},{"answer_index":1,"explanation_pt_br":"Para pedir permissão, colocamos ''can'' no início da pergunta: ''Can I go?''","options":["I can go?","Can I go?","Do I can go?","I can to go?"],"prompt":"How do you ask permission?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-324fbd7849fd', 'en', 'A1', 'Giving Simple Commands', 'In this lesson, you will learn how to give simple commands in English. Commands are very useful in daily life. For example, when you want a friend to help you, say "Help me, please." When you want someone to listen, say "Listen to me." To ask someone to come, say "Come here." Commands in English are easy. You just use the base form of the verb. The subject is usually not mentioned. For example, "Open the door" is a command. You do not say "You open the door." You can also use commands in polite ways. Add "please" at the beginning or end: "Please sit down" or "Sit down, please." Commands are important for giving instructions. For example, at work, a boss might say "Send the email" or "Call the client." At home, you might say "Wash the dishes" or "Clean your room." You can also use commands to give directions: "Turn left" or "Go straight." Remember, commands are very direct. Use them with friends or in informal situations. With strangers or in formal situations, it is better to ask politely, like "Could you help me?" Now, practice with these examples: "Stop!" "Wait!" "Look!" "Be quiet!" These are all commands.', 'What is a command?', '["a question","a statement","an instruction to do something","a greeting"]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"Um comando é uma instrução para fazer algo, como ''Sente-se'' ou ''Abra a porta''.","options":["a question","a statement","an instruction to do something","a greeting"],"prompt":"What is a command?"},{"answer_index":1,"explanation_pt_br":"A frase ''Open the window'' é um comando porque usa o verbo no imperativo (base form) sem sujeito.","options":["Are you hungry?","Open the window.","She is my friend.","He likes coffee."],"prompt":"Which sentence is a command?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-8b2b3b030882', 'en', 'A1', 'Asking Questions in English', 'Asking questions is very important in English. We use yes/no questions to ask for simple answers. For example: "Are you a student?" The answer is "Yes, I am" or "No, I''m not." We also have WH-questions to ask for information. We use question words like What, Where, When, Who, Why, and How.

Look at these examples: "What is your name?", "Where do you live?", "When is your birthday?", "Who is your teacher?", "Why are you happy?", and "How are you?" Remember, for yes/no questions, we start with the verb. For WH-questions, we start with the question word.

Let''s practice with a short dialogue. Ana is new in class. She asks: "Are you from Brazil?" Leo answers: "Yes, I am. And you?" Ana says: "I am from Brazil too. What about you? Where do you study?" Leo answers: "I study at a language school."', 'What is the answer to the question ''Are you a student?'' if you are not a student?', '["Yes, I am.","No, I''m not.","I don''t know.","Maybe."]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"A resposta ''No, I''m not'' é usada para responder negativamente a uma pergunta do tipo sim/não.","options":["Yes, I am.","No, I''m not.","I don''t know.","Maybe."],"prompt":"What is the answer to the question ''Are you a student?'' if you are not a student?"},{"answer_index":2,"explanation_pt_br":"A palavra ''Where'' pergunta sobre lugar, por isso a opção correta é ''Where do you live?''.","options":["Who is your teacher?","When is your birthday?","Where do you live?","Why are you happy?"],"prompt":"Which question asks for a place?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-e94849692231', 'en', 'A1', 'Where Is It?', 'Hello! Today we learn about prepositions: in, on, under, and next to. These words help us say where things are.

Look at your room. Your phone is on the table. Your book is in your bag. The cat is under the chair. The lamp is next to the bed.

In class, the teacher is at the front. The students are in their chairs. The clock is on the wall. The board is next to the door.

Now, let''s answer two questions. Choose the correct preposition.', 'The cat is ________ the table. (The cat is not on the table!)', '["in","on","under","next to"]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"Usamos ''under'' para dizer que algo está embaixo de outra coisa. O gato está embaixo da mesa.","options":["in","on","under","next to"],"prompt":"The cat is ________ the table. (The cat is not on the table!)"},{"answer_index":0,"explanation_pt_br":"Usamos ''in'' para algo dentro de um espaço. O livro está dentro da bolsa.","options":["in","on","under","next to"],"prompt":"The book is ________ the bag."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-ba8b5a631f75', 'en', 'A1', 'Some, Any, and Quantifiers', 'In English, we use ''some'' and ''any'' to talk about amounts. Use ''some'' in positive sentences: ''I have some friends.'' Use ''any'' in negative sentences and questions: ''I don''t have any money.'' ''Do you have any brothers?'' We also use simple quantifiers like ''a lot of'', ''many'', ''much'', ''a few'', and ''a little''.

For things we can count, we use ''many'' and ''a few''. For example: ''How many apples do you have?'' ''I have a few apples.'' For things we cannot count, we use ''much'' and ''a little''. For example: ''How much water do you drink?'' ''I drink a little water.'' ''A lot of'' is for both count and non-count nouns: ''She has a lot of books.'' ''He has a lot of time.'' Let''s practice!

Here are some tips: use ''some'' in offers and requests. For example: ''Would you like some coffee?'' ''Can I have some water?'' Use ''any'' in questions and negatives. For example: ''Is there any milk?'' ''There isn''t any bread.'' Remember, ''some'' is for positive, ''any'' is for negative and question.', 'Choose the correct sentence.', '["I have some water.","I don''t have some water.","Do you have some water?","I need some help."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"''some'' é usado em frases afirmativas. ''any'' é usado em negativas e perguntas. A alternativa A está correta.","options":["I have some water.","I don''t have some water.","Do you have some water?","I need some help."],"prompt":"Choose the correct sentence."},{"answer_index":1,"explanation_pt_br":"Para substantivos contáveis (como ''apples''), usamos ''how many''.","options":["How much","How many","What much","What many"],"prompt":"Complete the question: ''______ apples do you have?''"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-4012565ba84b', 'en', 'A1', 'I, You, We: First Words in English', 'Hello! Welcome to your first English lesson. Today we will learn about pronouns and the verb ''to be''. Pronouns are words like ''I'', ''you'', ''we'', and ''they''. We use them to talk about people. The verb ''to be'' is very important. It means ''ser'' or ''estar'' in Portuguese.

Look at the sentences: ''I am a teacher.'' ''You are a student.'' ''We are friends.'' The verb changes with the pronoun. ''I'' uses ''am'' because it is only about you. ''You'' uses ''are'' for one person or many people. ''We'' uses ''are'' for a group that includes you.

Now, let''s practice! Here is a dialogue: Maria says, ''I am from Brazil.'' Her friend asks, ''Are you from São Paulo?'' Maria answers, ''No, we are from Rio de Janeiro.'' Now you try!', 'Choose the correct pronoun: ''___ am a student.''', '["I","You","We","They"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Correto! ''I'' é o pronome que usamos para falar de nós mesmos. ''Am'' é a forma do verbo ''to be'' para ''I''.","options":["I","You","We","They"],"prompt":"Choose the correct pronoun: ''___ am a student.''"},{"answer_index":2,"explanation_pt_br":"Correto! ''They'' é usado para várias pessoas ou coisas. ''Are'' é a forma do verbo ''to be'' para ''they''.","options":["I","She","They","He"],"prompt":"Complete the sentence: ''___ are my friends.''"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-ca1720537c63', 'en', 'A1', 'Have and Has: Things I Own', 'Hello! Today we talk about things we have. In English, we use ''have'' and ''has'' to show possession. I have a book. You have a pen. He has a car. She has a cat. We use ''have'' with I, you, we, they. We use ''has'' with he, she, it. For example: ''They have a house.'' ''It has a tail.'' Remember: ''have'' and ''has'' are for things you own or have with you. Now, let''s practice. Look at the pictures in your mind. What do you have? I have a phone. She has a bag. We have many things. This is important for everyday talk. Keep learning!', 'Choose the correct sentence.', '["I has a car.","I have a car.","I haves a car.","I has car."]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"Com ''I'', usamos ''have''. A forma ''has'' é para he/she/it.","options":["I has a car.","I have a car.","I haves a car.","I has car."],"prompt":"Choose the correct sentence."},{"answer_index":1,"explanation_pt_br":"Com ''She'', usamos ''has''.","options":["have","has","having","haves"],"prompt":"Complete: She ___ a dog."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-c20a5ce3aa3b', 'en', 'A1', 'Daily Routines', 'Many people have a daily routine. They wake up in the morning. They eat breakfast and go to work. They have lunch at midday. After work, they go home. At night, they watch TV or read a book. Then, they sleep. A daily routine helps us organize our day. It gives us time for work, family, and rest. Simple present is the tense we use to talk about habits and routines.', 'What do many people do in the morning?', '["They sleep.","They eat breakfast and go to work.","They watch TV.","They read a book."]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"O texto diz: ''They wake up in the morning. They eat breakfast and go to work.'' Portanto, a resposta correta é ''They eat breakfast and go to work.''","options":["They sleep.","They eat breakfast and go to work.","They watch TV.","They read a book."],"prompt":"What do many people do in the morning?"},{"answer_index":2,"explanation_pt_br":"O texto diz: ''They have lunch at midday.'' Portanto, a resposta correta é ''At midday.''","options":["In the morning.","At night.","At midday.","In the afternoon."],"prompt":"When do they have lunch?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-aca965171f39', 'en', 'A1', 'This, That, My and Your', 'Hello! Today we learn about possessives and demonstratives. They are very useful. We use ''this'' for things near us. For example, "This book is mine." We use ''that'' for things far from us. For example, "That car is red."

Possessives show ownership. In English, we say "my" for me and "your" for you. For example, "My phone is new" and "Your bag is old." These words are easy. You put them before a noun. For example, "my house" and "your family."

In Portuguese, you say "meu/minha" for my and "seu/sua" for your. But in English, it is simple: my and your. Remember: this/that for distance, my/your for possession. Practice and you will learn fast!', 'Complete: "______ is my phone." (near me)', '["That","This","Those","These"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"Usamos ''this'' para coisas perto de nós no singular. ''That'' é para longe. ''These'' e ''those'' são plurais.","options":["That","This","Those","These"],"prompt":"Complete: \"______ is my phone.\" (near me)"},{"answer_index":0,"explanation_pt_br":"''This'' é singular, então usamos ''is'' e ''book'' no singular. ''Your'' mostra posse corretamente.","options":["This is your book.","This is your books.","These is your book.","That are your book."],"prompt":"Choose the correct sentence:"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-ab137b723fe8', 'en', 'A1', 'There is / There are', 'Hello! Today we learn ''there is'' and ''there are''. We use ''there is'' for one thing. We use ''there are'' for two or more things. For example: ''There is a book on the table.'' ''There are three books on the table.'' In questions, we say ''Is there a book?'' and ''Are there any books?'' We use ''any'' in questions with plural. Look at your room. There is a bed. There are two windows. There is a computer. There are some pictures. Can you see? Good! Now, let''s practice.', 'Choose the correct sentence.', '["There is a cat on the sofa.","There are a cat on the sofa.","There is two cats on the sofa.","There are a cats on the sofa."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Usamos ''there is'' para uma coisa (singular). ''a cat'' é singular, então ''there is'' é correto.","options":["There is a cat on the sofa.","There are a cat on the sofa.","There is two cats on the sofa.","There are a cats on the sofa."],"prompt":"Choose the correct sentence."},{"answer_index":0,"explanation_pt_br":"Em perguntas com singular, usamos ''Is there'' e ''any'' para perguntar sobre quantidade. ''Milk'' é incontável, então usamos ''Is there''.","options":["Is there any milk?","Are there any milk?","There is any milk?","There are any milk?"],"prompt":"Choose the correct question."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-edb9748cd7e5', 'en', 'A1', 'Can I use your phone?', 'In this lesson, you will learn how to talk about ability and permission. In English, we use the word "can" for both. For example, "I can swim" means you know how to swim. "Can I go to the bathroom?" means you are asking for permission. It is a very useful word! You can use it in many situations: with friends, at work, or in a store. When you want to ask for permission, you say "Can I...?" For example, "Can I sit here?" or "Can I open the window?" When you want to talk about ability, you say "I can..." or "He can...". For example, "She can speak Portuguese." or "They can cook very well." The word "can" is always followed by the base form of the verb. For example, "I can play guitar" (not "I can plays"). You can also make negative sentences with "can''t" (short for cannot). For example, "I can''t swim." or "He can''t drive." Remember, "can" is a modal verb, so it does not change with he, she, or it. We say "he can" not "he cans". Now, let''s practice with some questions!', 'What does "can" mean when you say "I can swim"?', '["I like swimming.","I know how to swim.","I want to swim.","I am swimming now."]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"Quando dizemos \"I can swim\", estamos falando de habilidade, ou seja, sabemos nadar. As outras opções falam de gostar, querer ou ação no momento.","options":["I like swimming.","I know how to swim.","I want to swim.","I am swimming now."],"prompt":"What does \"can\" mean when you say \"I can swim\"?"},{"answer_index":0,"explanation_pt_br":"Para pedir permissão, usamos \"Can I...?\" que significa \"Posso...?\". As outras formas estão incorretas em inglês.","options":["Can I use your phone?","I can use your phone.","Do I can use your phone?","I can to use your phone."],"prompt":"How do you ask for permission to use your friend''s phone?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-5f6ddf33d737', 'en', 'A1', 'Asking Questions in English', 'Asking questions is very important in English. You can ask yes/no questions and WH questions. Yes/no questions have answers ''yes'' or ''no''. WH questions ask for information. They start with words like ''what'', ''where'', ''when'', and ''who''.

Look at these examples. "Do you like coffee?" is a yes/no question. "Where do you live?" is a WH question. In yes/no questions, we use ''do'' or ''does'' at the start. In WH questions, we put the WH word first, then ''do'' or ''does''.

Practice asking questions and you will learn a lot!', 'Which question is a yes/no question?', '["Where is the bank?","Do you speak English?","What time is it?","Who is your teacher?"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"A pergunta ''Do you speak English?'' pode ser respondida com ''yes'' ou ''no''.","options":["Where is the bank?","Do you speak English?","What time is it?","Who is your teacher?"],"prompt":"Which question is a yes/no question?"},{"answer_index":3,"explanation_pt_br":"A pergunta ''Where do you work?'' começa com ''where'' e pede uma informação específica, não apenas sim ou não.","options":["Are you a student?","Do you have a car?","Can you swim?","Where do you work?"],"prompt":"Which question asks for information?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-39c2b489d3f1', 'en', 'A1', 'Where is It?', '"Where is my phone?" In English, small words like ''in'', ''on'', ''under'', and ''next to'' show where things are. These words are called prepositions. They help you talk about positions.

Example: The book is **on** the table. The cat is **under** the chair. My bag is **next to** the door. The keys are **in** my pocket. This is very useful in daily life.

Let''s practice with a picture. A ball is in a box. A dog is on a bed. A car is under a tree. A girl is next to a window. Now, answer the questions below.', 'The cat is ______ the table.', '["on","in","under","next to"]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"Se o gato está embaixo da mesa, usamos ''under''.","options":["on","in","under","next to"],"prompt":"The cat is ______ the table."},{"answer_index":1,"explanation_pt_br":"O livro está sobre a prateleira, então ''on'' é a preposição correta.","options":["in","on","under","next to"],"prompt":"The book is ______ the shelf."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-e56d2e11fc18', 'en', 'A1', 'Using Some and Any', 'Hello! Today we learn about ''some'' and ''any''. We use ''some'' in positive sentences. For example, ''I have some friends.'' We use ''any'' in negative sentences and questions. For example, ''I don''t have any money.'' and ''Do you have any brothers?'' 

''Some'' and ''any'' talk about things we don''t count exactly. For example, ''There is some water.'' We also use ''some'' in offers: ''Would you like some coffee?'' Remember: use ''some'' with positive, ''any'' with negative and questions. 

Practice! Read the examples. Then answer the questions below.', 'Which sentence is correct?', '["I have some apples.","I have any apples.","I don''t have some apples.","Do you have some apples?"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Use ''some'' in positive sentences. ''I have some apples.'' is correct.","options":["I have some apples.","I have any apples.","I don''t have some apples.","Do you have some apples?"],"prompt":"Which sentence is correct?"},{"answer_index":1,"explanation_pt_br":"In questions, we use ''any''. ''Do you have any water?'' is correct.","options":["Do you have some water?","Do you have any water?","You have any water?","You don''t have any water?"],"prompt":"Which question is correct?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-8d3fe86c41d1', 'en', 'A1', 'I am, You are, We are: Using ''to be'' with Pronouns', 'Hello! Today we learn about the verb ''to be'' in English. This verb is very important. We use it to say who we are, how we are, and where we are. In Portuguese, we say ''eu sou'', ''você é'', ''nós somos''. In English, we say ''I am'', ''you are'', ''we are''.

Look at the pronouns: I, you, he, she, it, we, they. Each pronoun has a form of ''to be'': I am, you are, he is, she is, it is, we are, they are. For example: ''I am a student.'' ''You are my friend.'' ''We are from Brazil.''

Now, let''s practice. Remember: ''am'' for I, ''is'' for he, she, it, and ''are'' for you, we, they. Be careful with ''you'' – it is always ''are'', even for one person or many. This is easy! Let''s do the questions.', 'Choose the correct form of ''to be'' for ''she''.', '["is","am","are","be"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Para ''she'' (ela), usamos ''is''. Por exemplo: ''She is a teacher.''","options":["is","am","are","be"],"prompt":"Choose the correct form of ''to be'' for ''she''."},{"answer_index":2,"explanation_pt_br":"A forma correta é ''We are students.'' (Nós somos estudantes). ''I am'', ''You are'', ''He is'', ''She is'', ''It is'', ''We are'', ''They are''.","options":["I are happy.","You is my friend.","We are students.","He am tall."],"prompt":"Which sentence is correct?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-f63d880e3542', 'en', 'A1', 'What Do You Have?', 'Hello! Today we talk about things we have. In English, we use the verb ''have'' to show possession. For example, you can say ''I have a phone'' or ''She has a car''. Use ''have'' with I, you, we, and they. Use ''has'' with he, she, and it. Let''s see some examples.

Look at Ana. She has a new book. Her friend, Pedro, has a bicycle. They have many things. Do you have a pet? Yes, I have a dog. My dog has a toy. We have a happy family.

Remember: use ''have'' or ''has'' to talk about what you own. Now, let''s practice!', 'Which sentence is correct?', '["I has a car.","I have a car.","I haves a car.","I having a car."]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"Usamos ''have'' com ''I''. A forma correta é ''I have a car.''","options":["I has a car.","I have a car.","I haves a car.","I having a car."],"prompt":"Which sentence is correct?"},{"answer_index":1,"explanation_pt_br":"Com ''she'', usamos ''has''. A forma correta é ''She has a cat.''","options":["She have a cat.","She has a cat.","She haves a cat.","She having a cat."],"prompt":"Choose the correct sentence for she."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-270490b86cd2', 'en', 'A1', 'Daily Routines', 'Every day, Ana wakes up at seven o''clock. She gets up and takes a shower. Then, she eats breakfast with her family. She drinks coffee and eats bread with butter. After breakfast, she brushes her teeth and gets dressed. She goes to work by bus. She works in a small office in the city. She talks to many people and helps them. At noon, she has lunch with her friends. In the afternoon, she works on her computer and writes emails. In the evening, she goes home. She cooks dinner and watches TV with her husband. She reads a book before bed. She sleeps at eleven o''clock. Every day is the same, but she likes her routine.', 'What time does Ana wake up?', '["At six o''clock","At seven o''clock","At eight o''clock","At nine o''clock"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"O texto diz ''Ana wakes up at seven o''clock''.","options":["At six o''clock","At seven o''clock","At eight o''clock","At nine o''clock"],"prompt":"What time does Ana wake up?"},{"answer_index":1,"explanation_pt_br":"O texto diz ''After breakfast, she brushes her teeth and gets dressed''.","options":["She goes to work","She brushes her teeth","She watches TV","She reads a book"],"prompt":"What does Ana do after breakfast?"}]'::jsonb, 0, true)
