insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-1cbd2ced95b4', 'en', 'A1', 'My Family', 'Hello! My name is Ana. I have a small family. This is my father. He is a doctor. This is my mother. She is a teacher. I have two brothers and one sister. My brothers are students. My sister is a child. We have a dog and a cat. The dog is big. The cat is small. We live in a house. The house has three rooms. I love my family!', 'How many brothers does Ana have?', '["One","Two","Three","Four"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"O texto diz: ''I have two brothers'' (Eu tenho dois irmãos).","options":["One","Two","Three","Four"],"prompt":"How many brothers does Ana have?"},{"answer_index":1,"explanation_pt_br":"O texto diz: ''My mother is a teacher'' (Minha mãe é professora).","options":["Doctor","Teacher","Student","Child"],"prompt":"What is Ana''s mother''s job?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-en-a1-1a1d8e4e9c0f', 'en', 'A1', 'There Is / There Are: Describing Places', 'Hello! Today we learn ''there is'' and ''there are''. We use ''there is'' for one thing. We use ''there are'' for many things.

Look at a room. There is a bed. There are two chairs. There is a lamp. There are books on the table.

In a city, there is a park. There are many cars. There is a school. There are restaurants. Is there a hospital? Yes, there is. Are there museums? No, there aren''t. Now you practice!', 'Look at a room. There is one bed. There are two chairs. What is true?', '["There are one bed.","There is two chairs.","There is a bed.","There are a lamp."]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"A opção correta é ''There is a bed'' porque usamos ''there is'' para uma coisa (uma cama).","options":["There are one bed.","There is two chairs.","There is a bed.","There are a lamp."],"prompt":"Look at a room. There is one bed. There are two chairs. What is true?"},{"answer_index":3,"explanation_pt_br":"A opção correta é ''There is a park'' porque usamos ''there is'' para uma coisa (um parque). ''There are'' é para muitas coisas.","options":["There are a park.","There is many cars.","There are a park and a car.","There is a park."],"prompt":"In a city, there is a park and there are many cars. What is true?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-76c1ae4a7813', 'es', 'A1', 'Mi día con verbos irregulares', 'Cada mañana, yo **salgo** de casa a las siete. Primero, **voy** a la panadería y compro pan fresco. Luego, **hago** un café y desayuno con mi familia. Mis hijos **tienen** hambre y comen rápido.

En el trabajo, mi jefe **dice** que hoy hay muchas reuniones. Yo **pongo** los documentos en la mesa y **traigo** mi computadora. **Oigo** el teléfono y contesto. A veces, **vengo** al trabajo en autobús, pero hoy **vengo** en coche.

Por la tarde, **sé** que debo terminar un informe. **Puedo** hacerlo sin problemas. Al final, **estoy** cansado, pero contento. **Voy** a casa y **doy** un beso a mis hijos. Todos **están** felices.', '¿Qué hace la persona cada mañana?', '["Sale de casa a las siete.","Va a la escuela.","Compra un periódico.","Hace ejercicio."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"O texto diz: ''Cada mañana, yo salgo de casa a las siete.'' Portanto, a resposta correta é a primeira opção. As outras opções não são mencionadas no texto.","options":["Sale de casa a las siete.","Va a la escuela.","Compra un periódico.","Hace ejercicio."],"prompt":"¿Qué hace la persona cada mañana?"},{"answer_index":1,"explanation_pt_br":"O texto diz: ''Pero hoy vengo en coche.'' Isso indica que hoje ele vai de carro. A opção ''En autobús'' é mencionada como uma alternativa (''A veces, vengo al trabajo en autobús''), mas não é a opção de hoje. As outras opções não aparecem no texto.","options":["En autobús.","En coche.","A pie.","En bicicleta."],"prompt":"¿Cómo va la persona al trabajo hoy?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-056ddec7f0f3', 'es', 'A1', '¿Quién es? ¿Cómo está? ¿Qué hay?', 'Hola, amigos. Hoy vamos a aprender tres verbos muy importantes en español: ser, estar y hay. Son diferentes y se usan para cosas distintas.

Ser describe identidad y características permanentes. Por ejemplo, yo soy brasileña. Mi amigo es alto. Nosotros somos estudiantes.

Estar describe estados y lugares temporales. Por ejemplo, yo estoy cansada. El libro está en la mesa. Ellos están felices.

Hay significa ''existe'' o ''existen''. Es impersonal y se usa para hablar de la existencia. Por ejemplo, hay un perro en el parque. En mi casa hay tres habitaciones. No hay problemas.

Es importante recordar: ser para identidad, estar para estado o lugar, y hay para existencia. ¡Practiquemos con preguntas!', '¿Qué verbo usamos para hablar de la identidad de una persona?', '["ser","estar","hay","tener"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Usamos ser para identidad, como en ''Yo soy Ana''.","options":["ser","estar","hay","tener"],"prompt":"¿Qué verbo usamos para hablar de la identidad de una persona?"},{"answer_index":2,"explanation_pt_br":"Usamos ''hay'' para indicar existencia: ''hay muchos parques''.","options":["es","está","hay","son"],"prompt":"Completa: ''En mi ciudad _______ muchos parques.''"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-3eec953a76ec', 'es', 'A1', 'Mi día con tener, ir y hacer', 'Hola, soy Marta. Tengo 30 años y vivo en São Paulo. Todos los días tengo una rutina. Por la mañana, hago ejercicio en el parque. Después, voy al trabajo en autobús. En el trabajo, tengo muchas tareas. A las doce, hago una pausa para almorzar. Por la tarde, hago llamadas y respondo correos. A las seis, voy a casa. Por la noche, tengo tiempo libre. Hago mis actividades favoritas: leer y ver series. También voy al cine con amigos los viernes. Los sábados, hago compras en el mercado. Los domingos, voy a la casa de mi familia. Todos tenemos momentos especiales juntos.', '¿Qué hace Marta por la mañana?', '["Hace ejercicio.","Va al trabajo.","Hace compras.","Va al cine."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"O texto diz: ''Por la mañana, hago ejercicio en el parque.'' Portanto, a resposta correta é ''Hace ejercicio''.","options":["Hace ejercicio.","Va al trabajo.","Hace compras.","Va al cine."],"prompt":"¿Qué hace Marta por la mañana?"},{"answer_index":2,"explanation_pt_br":"O texto menciona: ''También voy al cine con amigos los viernes.'' Portanto, a resposta correta é ''Los viernes''.","options":["Los lunes.","Los miércoles.","Los viernes.","Los domingos."],"prompt":"¿Cuándo va Marta al cine?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-6b080d358afb', 'es', 'A1', '¿Qué te gusta?', 'Hola, ¿qué tal? Hoy vamos a hablar de gustos. En español, usamos el verbo GUSTAR para decir qué nos gusta. Por ejemplo: "Me gusta el café". "Me" significa "a mí". Cuando te gusta UNA cosa, usamos "gusta". Cuando te gustan VARIAS cosas, usamos "gustan". Por ejemplo: "Me gusta la playa" pero "Me gustan las playas".

También usamos GUSTAR para hablar de actividades. Después de GUSTAR, usamos un verbo en infinitivo. Por ejemplo: "Me gusta bailar". "Bailar" es infinitivo. En Brasil, la gente usa mucho "gostar de", pero en español es diferente. No decimos "Yo gusto de viajar". Decimos "Me gusta viajar".

Ahora, mira estas preguntas: "¿Te gusta el fútbol?" y "¿Te gustan los deportes?". Para responder, decimos "Sí, me gusta" o "No, no me gusta". ¡Practiquemos!', '¿Qué significa "Me gusta el café"?', '["Yo bebo café","Yo quiero café","El café me agrada","El café es malo"]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"A frase \"Me gusta el café\" significa que o café agrada a mim, que eu gosto de café. A opção correta é \"El café me agrada\".","options":["Yo bebo café","Yo quiero café","El café me agrada","El café es malo"],"prompt":"¿Qué significa \"Me gusta el café\"?"},{"answer_index":1,"explanation_pt_br":"Quando falamos de várias coisas (livros), usamos \"gustan\". Então: \"A Maria le gustan los libros\".","options":["gusta","gustan","gustar","gustamos"],"prompt":"Complete: \"A Maria le ________ los libros.\""}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-9a67c547653e', 'es', 'A1', 'Mi Rutina Diaria', 'Hola, soy Ana. Todas las mañanas me levanto a las seis. Primero, me ducho con agua caliente. Después, me visto y me peino. Luego, me desayuno con pan y café. Mi hermano Pablo también se levanta temprano. Él se lava la cara y se cepilla los dientes. Nosotros nos preparamos juntos para ir a la escuela. Mis padres se despiertan más tarde porque trabajan en la tarde. Ellos se bañan después de nosotros. En la noche, yo me acuesto a las diez. ¿Y tú? ¿A qué hora te levantas?', '¿A qué hora se levanta Ana?', '["a las cinco","a las seis","a las siete","a las ocho"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"No texto, Ana diz: ''me levanto a las seis''.","options":["a las cinco","a las seis","a las siete","a las ocho"],"prompt":"¿A qué hora se levanta Ana?"},{"answer_index":1,"explanation_pt_br":"O texto diz: ''Él se lava la cara y se cepilla los dientes.''","options":["se ducha","se lava la cara y se cepilla los dientes","se desayuna","se peina"],"prompt":"¿Qué hace Pablo después de levantarse?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-a11d22a681d4', 'es', 'A1', 'Mi Casa y Mis Cosas', 'Hola, yo soy Carlos. Esta es mi casa. Aquí está mi sala. Este es mi sofá y esta es mi mesa. Estos son mis libros y estas son mis plantas. Me gusta mi casa.

Estos son mis amigos: Ana y Luis. Aquellas son sus mochilas. Esta es la mochila de Ana, y esa es la mochila de Luis. Aquel es su perro, se llama Toby.

¿Y tú? ¿Cuál es tu casa? ¿Dónde están tus cosas?', '¿Qué es ''esta'' en la frase ''Esta es mi casa''?', '["Un objeto lejos","Un objeto cerca","Un objeto en la mano","Un objeto en otra habitación"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"''Esta'' é usado para algo que está perto de quem fala.","options":["Un objeto lejos","Un objeto cerca","Un objeto en la mano","Un objeto en otra habitación"],"prompt":"¿Qué es ''esta'' en la frase ''Esta es mi casa''?"},{"answer_index":0,"explanation_pt_br":"A mochila de Luis é dele, por isso usamos ''su''.","options":["Es su mochila.","Es mi mochila.","Es tu mochila.","Es nuestra mochila."],"prompt":"¿De quién es la mochila de Luis?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-86de052a2105', 'es', 'A1', 'El Colegio', 'Hoy es el primer día de clases. Ana entra en el colegio con su mochila. Ella ve a su amigo Luis en el patio. Luis tiene un cuaderno y dos libros. Ana dice: "¡Hola, Luis! ¿Qué tal?" Luis responde: "Bien, gracias. ¿Dónde están las profesoras?" Ana mira y dice: "Las profesoras están en la sala de profesores. Los estudiantes están en la clase." Ellos entran en la clase. La profesora María está en la pizarra. Ella es muy simpática. Ana y Luis se sientan en las sillas. La clase es interesante.', '¿Qué tiene Luis?', '["Una mochila","Un cuaderno y dos libros","Una silla","Una pizarra"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"O texto diz: ''Luis tiene un cuaderno y dos libros.'' Por isso, a resposta correta é ''Un cuaderno y dos libros''.","options":["Una mochila","Un cuaderno y dos libros","Una silla","Una pizarra"],"prompt":"¿Qué tiene Luis?"},{"answer_index":2,"explanation_pt_br":"O texto diz: ''Las profesoras están en la sala de profesores.'' Portanto, a resposta correta é ''En la sala de profesores''.","options":["En la clase","En el patio","En la sala de profesores","En la pizarra"],"prompt":"¿Dónde están las profesoras?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-44687b251e10', 'es', 'A1', 'Mi rutina diaria', 'Hola, soy Carlos. Todos los días me levanto a las seis de la mañana. Después, desayuno pan con café. A las siete, salgo de casa y voy al trabajo en autobús. Trabajo en una oficina y almuerzo a las doce. Por la tarde, hago ejercicio y a veces compro frutas en el mercado. Por la noche, ceno con mi familia y miro la televisión. A las diez, me acuesto. 

Los sábados, no trabajo. Me gusta descansar y leer un libro. A veces, visito a mis padres. Ellos viven cerca. Por la tarde, juego al fútbol con mis amigos. Los domingos, voy a la iglesia por la mañana y por la tarde paseo en el parque. 

Mi amiga Lucía tiene una rutina diferente. Ella se levanta a las ocho, porque trabaja por la tarde. Por la mañana, estudia inglés y cocina. A las dos, va a su tienda. Ella vende ropa. Yo la veo los miércoles. Ella siempre dice: "La rutina es importante para tener una vida sana". 

Todo esto es mi vida normal.', '¿Qué hace Carlos a las seis de la mañana?', '["Se levanta","Desayuna","Sale de casa","Se acuesta"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"O texto diz: ''Todos los días me levanto a las seis de la mañana.'' Portanto, ele se levanta às seis.","options":["Se levanta","Desayuna","Sale de casa","Se acuesta"],"prompt":"¿Qué hace Carlos a las seis de la mañana?"},{"answer_index":0,"explanation_pt_br":"O texto afirma: ''Los sábados, no trabajo. ... A veces, visito a mis padres.'' Portanto, a resposta correta é ''Los sábados''.","options":["Los sábados","Los domingos","Los miércoles","Todos los días"],"prompt":"¿Cuándo visita Carlos a sus padres?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-1f3e555d7396', 'es', 'A1', '¿Ser, Estar o Hay?', 'En español, hay tres formas de decir ''to be'' en portugués: ser, estar y hay. Cada una tiene un uso diferente.

**Ser** se usa para describir características permanentes, como la identidad, la nacionalidad o la profesión. Por ejemplo: *Yo soy profesora*. **Estar** se usa para estados temporales o ubicación. Por ejemplo: *Yo estoy en casa* o *Yo estoy cansada*. **Hay** se usa para expresar existencia, como ''existe'' o ''há'' en portugués. Por ejemplo: *Hay un libro en la mesa*.

Es importante practicar cuándo usar cada verbo. Muchos brasileños confunden *estar* y *hay* porque en portugués se usa ''tem'' para existencia. Pero en español, usamos *hay*.

¿Listo? Vamos a practicar.', '¿Cuál verbo usamos para describir una característica permanente como la profesión?', '["ser","estar","hay","tener"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Usamos ''ser'' para características permanentes, como profesión, identidad, nacionalidad.","options":["ser","estar","hay","tener"],"prompt":"¿Cuál verbo usamos para describir una característica permanente como la profesión?"},{"answer_index":2,"explanation_pt_br":"Usamos ''hay'' para expresar existencia, equivalente a ''há/existe'' em português.","options":["ser","estar","hay","haber"],"prompt":"¿Cuál verbo usamos para expresar existencia?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-e755621409be', 'es', 'A1', 'Mi día con tener, ir y hacer', 'Hola, soy Marta. Todos los días yo tengo mucho trabajo. Por la mañana, yo hago café y desayuno. Después, yo voy al trabajo en autobús. Mi trabajo es interesante. Yo tengo muchos amigos allí. Ellos hacen preguntas y yo respondo. Al mediodía, nosotros vamos a un restaurante. Yo como una ensalada y hago una llamada. Por la tarde, yo tengo una reunión. Yo hago preguntas y escucho. Después, yo voy a casa. Por la noche, yo hago ejercicio y voy al parque. Yo tengo tiempo para leer. Hago mis tareas y voy a dormir.', '¿Qué hace Marta por la mañana?', '["Hace café","Va al parque","Hace ejercicio","Va al restaurante"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"O texto diz: ''Por la mañana, yo hago café y desayuno.''","options":["Hace café","Va al parque","Hace ejercicio","Va al restaurante"],"prompt":"¿Qué hace Marta por la mañana?"},{"answer_index":1,"explanation_pt_br":"O texto diz: ''Al mediodía, nosotros vamos a un restaurante.''","options":["Al trabajo","Al restaurante","A casa","Al parque"],"prompt":"¿A dónde va Marta al mediodía?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-2adb22c47743', 'es', 'A1', 'Me gusta viajar', 'Me gusta viajar. Me gustan los viajes. Me gusta la playa y me gustan las montañas. Me gusta la comida brasileña. Me gusta el fútbol. Me gustan los carnavales. Y a ti, ¿qué te gusta?', '¿Qué le gusta a la persona?', '["Cocinar","Viajar","Bailar","Cantar"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"A pessoa diz ''Me gusta viajar'', então ela gosta de viajar.","options":["Cocinar","Viajar","Bailar","Cantar"],"prompt":"¿Qué le gusta a la persona?"},{"answer_index":0,"explanation_pt_br":"A pessoa menciona ''Me gusta la playa'' e ''me gustan las montañas'', mas entre as opções, a única mencionada é ''las playas''.","options":["Las playas","Los libros","Las películas","Los perros"],"prompt":"¿Qué le gustan a la persona?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-34771fa7270f', 'es', 'A1', '¿Este o ese?', 'Hola, amigos. Hoy hablamos de los posesivos y demostrativos en español. Usamos los posesivos para decir de quién es algo. Por ejemplo, “mi casa” o “tus amigos”. Los demostrativos señalan cosas. “Este” es para cosas cerca de mí. “Ese” es para cosas cerca de ti. “Aquel” es para cosas lejos de nosotros.

En la casa, mi madre cocina en esta cocina. Ese plato es de mi hermano. Aquella ventana está abierta. ¿Y tú? ¿Cuál es tu silla? ¿Esta o esa?', '¿Qué palabra usamos para una cosa cerca de mí?', '["ese","aquel","este","mi"]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"Usamos ''este'' para cosas perto de quem fala.","options":["ese","aquel","este","mi"],"prompt":"¿Qué palabra usamos para una cosa cerca de mí?"},{"answer_index":2,"explanation_pt_br":"Usamos ''aquel'' para coisas distantes.","options":["este","ese","aquel","mi"],"prompt":"¿Qué palabra señala una cosa lejos?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-d6d69a64b71f', 'es', 'A1', 'Uso de ''a'', ''de'', ''en'', ''con''', 'En español, las preposiciones ''a'', ''de'', ''en'' y ''con'' son muy importantes. Se usan para conectar palabras. Por ejemplo, usamos ''a'' para hablar de destino: ''Voy a Brasil''. Usamos ''de'' para hablar de origen: ''Soy de Brasil''. Usamos ''en'' para hablar de lugar: ''Estoy en casa''. Usamos ''con'' para hablar de compañía: ''Voy con amigos''.

Practica con estos ejemplos: ''María va a la escuela'', ''El libro es de Juan'', ''Pedro está en Madrid'', ''Yo como con mis amigos''. Ahora lee el texto y haz las preguntas.

Hola, me llamo Ana. Soy de Brasil, pero ahora vivo en España. Trabajo con mi amiga Lucía en una escuela. Todos los días voy a la escuela en autobús. Por la tarde, como con mis compañeros en un restaurante. Me gusta mucho mi vida en España.', '¿De dónde es Ana?', '["España","Brasil","México","Argentina"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"O texto diz: ''Soy de Brasil'', ou seja, Ana é do Brasil.","options":["España","Brasil","México","Argentina"],"prompt":"¿De dónde es Ana?"},{"answer_index":1,"explanation_pt_br":"O texto diz: ''trabajo ... en una escuela'', então Ana trabalha em uma escola.","options":["En un hospital","En una escuela","En un restaurante","En una oficina"],"prompt":"¿Dónde trabaja Ana?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-f0f7c013dc4b', 'es', 'A1', 'El libro y los libros', 'En español, las cosas tienen género: masculino o femenino. Generalmente, los sustantivos que terminan en -o son masculinos y usan el artículo ''el'' (singular) o ''los'' (plural). Por ejemplo: el libro, los libros. Los que terminan en -a son femeninos y usan ''la'' (singular) o ''las'' (plural). Por ejemplo: la casa, las casas.

También hay excepciones, como ''el día'' (masculino a pesar de terminar en -a) y ''la mano'' (femenino a pesar de terminar en -o). Pero no te preocupes, con práctica lo aprenderás.

Para plural, añadimos -s o -es. Por ejemplo: el libro -> los libros, la casa -> las casas, el papel -> los papeles. Recuerda que los artículos también cambian en plural.', '¿Cuál es el plural de ''la casa''?', '["las casas","los casas","la casas"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"''casa'' termina em -a, então é feminino. O plural de ''la'' é ''las'', e adicionamos -s para formar o plural: ''las casas''.","options":["las casas","los casas","la casas"],"prompt":"¿Cuál es el plural de ''la casa''?"},{"answer_index":1,"explanation_pt_br":"''manos'' é plural e feminino (a palavra ''mano'' é exceção, termina em -o mas é feminina). O plural feminino é ''las''.","options":["las","los","el","la"],"prompt":"¿Cuál es el artículo correcto para ''manos''?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-77a16855e086', 'es', 'A1', 'Mi día con verbos irregulares', 'Todos los días, yo (1) ______ a las siete. Después, (2) ______ café con leche y pan. Mi amiga Laura (3) ______ a las ocho y media. Ella no (4) ______ desayunar porque tiene prisa. Por la tarde, yo (5) ______ en una oficina. Laura (6) ______ en un hospital. Ella (7) ______ mucha a sus pacientes. Por la noche, nosotros (8) ______ en casa. A veces, yo (9) ______ la tele, pero Laura prefiere leer. Ella (10) ______ que leer es muy interesante. Y tú, ¿qué (11) ______ todos los días?', '¿Cuál es la forma correcta del verbo ''despertarse'' en la primera persona del singular?', '["me despierto","te despiertas","se despierta","nos despertamos"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"A forma correta é ''me despierto'', porque o verbo ''despertarse'' é reflexivo e irregular. Na primeira pessoa do singular, a mudança de ''e'' para ''ie'' ocorre: yo me despierto.","options":["me despierto","te despiertas","se despierta","nos despertamos"],"prompt":"¿Cuál es la forma correcta del verbo ''despertarse'' en la primera persona del singular?"},{"answer_index":2,"explanation_pt_br":"O verbo ''ir'' é totalmente irregular. Na terceira pessoa do singular, usamos ''va''. Por exemplo: ''Él va al trabajo.''","options":["voy","vas","va","vamos"],"prompt":"¿Cuál es la forma correcta del verbo ''ir'' en la tercera persona del singular?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-b0d33ff4b94c', 'es', 'A1', '¿Quién soy? ¿Dónde estoy?', 'En español, usamos tres verbos para describir personas, lugares y cosas: SER, ESTAR y HAY.

SER es para características permanentes: "Yo soy Ana", "El cielo es azul".

ESTAR es para estados temporales y ubicaciones: "Yo estoy en casa", "Ellos están cansados".

HAY es para existencia: "Hay un libro en la mesa", "En mi ciudad hay muchos parques".

Ahora, practica con estas preguntas.', 'Completa: Yo ____ estudiante.', '["soy","estoy","hay","eres"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Usamos SER para describir una característica permanente, como profesión.","options":["soy","estoy","hay","eres"],"prompt":"Completa: Yo ____ estudiante."},{"answer_index":2,"explanation_pt_br":"HAY se usa para indicar existencia: ''Hay muchos libros''.","options":["Son","Están","Hay","Es"],"prompt":"Completa: ____ muchos libros en la biblioteca."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-57599f9dd891', 'es', 'A1', 'Mis planes para el fin de semana', 'Hoy es viernes. Yo tengo muchos planes para el fin de semana. El sábado por la mañana, yo voy a hacer ejercicio en el parque. Me gusta correr y caminar. Después, voy a visitar a mis abuelos. Ellos tienen una casa pequeña y bonita. Vamos a hacer una comida juntos.

El domingo, yo no tengo trabajo. Voy a ir al cine con mis amigos. Vamos a ver una película de acción. También tengo que hacer mis tareas de español. Yo quiero hacer un proyecto sobre mi ciudad. Mis amigos dicen que es muy interesante.

La próxima semana, yo voy a empezar un curso de cocina. Voy a aprender a hacer platos típicos de Brasil. Mi hermana tiene un libro de recetas y me va a prestar. Hacer nuevas cosas es emocionante.', '¿Qué va a hacer la persona el sábado por la mañana?', '["Ir al cine","Hacer ejercicio en el parque","Visitar a sus abuelos","Empezar un curso de cocina"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"O texto diz: ''El sábado por la mañana, yo voy a hacer ejercicio en el parque.'' Portanto, a resposta correta é ''Hacer ejercicio en el parque''.","options":["Ir al cine","Hacer ejercicio en el parque","Visitar a sus abuelos","Empezar un curso de cocina"],"prompt":"¿Qué va a hacer la persona el sábado por la mañana?"},{"answer_index":0,"explanation_pt_br":"O texto diz: ''También tengo que hacer mis tareas de español.'' Portanto, a resposta correta é ''Hacer sus tareas de español''.","options":["Hacer sus tareas de español","Visitar a sus abuelos","Ver una película","Cocinar con su hermana"],"prompt":"¿Qué tiene que hacer la persona el domingo?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-1f0727d5992b', 'es', 'A1', '¿Qué te gusta?', '¡Hola! Hoy vamos a hablar de gustos. En español, para decir que algo te gusta, usamos el verbo GUSTAR. Es muy especial.

Primero, mira: A mí ME GUSTA el café. A ti TE GUSTA la música. A él LE GUSTA el fútbol. ¿Entendido? Usamos ME, TE, LE, NOS, OS, LES antes de GUSTA.

¿Y si te gustan varias cosas? Entonces usamos GUSTAN. Por ejemplo: A mí ME GUSTAN los gatos. A ti TE GUSTAN los libros. A ella LE GUSTAN las flores.

También puedes decir “A mí también” o “A mí no”. Por ejemplo:
– Me gusta el chocolate.
– A mí también.
– No me gusta el café.
– A mí no.

Es muy fácil, ¿verdad? Practiquemos con unas preguntas.', '¿Qué usamos con GUSTA?', '["una cosa","dos cosas","tres cosas","cuatro cosas"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Usamos GUSTA quando gostamos de uma coisa só. Para várias coisas, usamos GUSTAN.","options":["una cosa","dos cosas","tres cosas","cuatro cosas"],"prompt":"¿Qué usamos con GUSTA?"},{"answer_index":1,"explanation_pt_br":"''Los gatos'' é plural, então usamos ''gustan''.","options":["Me gusta los gatos.","Me gustan los gatos.","Me gusta el gato.","Me gustan el gato."],"prompt":"¿Cuál es correcto?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-49f2d8fc5187', 'es', 'A1', 'Mi Rutina Diaria', 'Hola, soy Ana. Me llamo Ana y soy de Brasil. Todos los días me levanto a las seis y media. Me ducho con agua fría y me visto rápido. Después, desayuno pan y café. A las ocho, me voy al trabajo. En el trabajo, me siento delante de la computadora. A las doce, almuerzo con mis compañeros. Ellos se llaman Carlos y Marta. Por la tarde, me siento otra vez. A las seis, vuelvo a casa. Me relajo con música y ceno. Me acuesto a las diez. Mi rutina es simple, pero me gusta.', '¿Qué hace Ana después de ducharse?', '["Se viste","Se levanta","Se acuesta","Se sienta"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"No texto, Ana diz: ''Me ducho con agua fría e me visto rápido.'' Portanto, depois de se vestir, ela se veste.","options":["Se viste","Se levanta","Se acuesta","Se sienta"],"prompt":"¿Qué hace Ana después de ducharse?"},{"answer_index":0,"explanation_pt_br":"No texto: ''Ellos se llaman Carlos y Marta.''","options":["Carlos y Marta","Ana y Pedro","Carlos y Ana","Marta y Julia"],"prompt":"¿Cómo se llaman los compañeros de Ana?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-b982629b44eb', 'es', 'A1', 'Mis cosas y esas cosas', 'Hola, ¿cómo estás? Hoy vamos a aprender a hablar de las cosas que tenemos y de las cosas que vemos. Para eso, usamos palabras como "mi", "tu" y "su". Por ejemplo: "Mi casa es pequeña." "¿Tu teléfono es nuevo?" "Su libro es interesante."

También usamos "este", "ese" y "aquel" para señalar cosas. "Este" es para cosas cerca de mí. "Ese" es para cosas cerca de ti. "Aquel" es para cosas lejos. Por ejemplo: "Este es mi lápiz." "Ese es tu cuaderno." "Aquel es su coche."

Practiquemos con ejemplos cotidianos. Mira a tu alrededor. ¿Qué ves? ¿Un libro? ¿Una mochila? Usa las palabras nuevas para describir. Recuerda: los posesivos y demostrativos nos ayudan a comunicar mejor.', '¿Qué palabra usamos para hablar de algo que está lejos?', '["este","ese","aquel","mi"]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"Usamos ''aquel'' para cosas que están lejos. ''Este'' para cerca, ''ese'' para cerca de la otra persona, y ''mi'' es posesivo.","options":["este","ese","aquel","mi"],"prompt":"¿Qué palabra usamos para hablar de algo que está lejos?"},{"answer_index":0,"explanation_pt_br":"A frase indica que o livro está perto de quem fala, então usamos ''Este''. ''Ese'' e ''Aquel'' indicam distância, e ''Tu'' é possessivo.","options":["Este","Ese","Aquel","Tu"],"prompt":"Completa: ______ libro es mío."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-cee29f6c79cc', 'es', 'A1', 'Somos Diversos: Cuerpo, Mente y Máquinas', 'El cuerpo humano es increíble. El corazón bombea sangre y los músculos nos ayudan a movernos. También tenemos un cerebro que piensa y siente. La homeostasis es un equilibrio: el cuerpo trabaja para estar bien.

Las computadoras también son máquinas fascinantes. Tienen partes como el disco duro y la memoria. Pero las personas somos diferentes: tenemos emociones y sentimientos. Las personas y las máquinas son distintos, pero ambos necesitan energía.

El guaraní es un idioma de Paraguay. Es una lengua con mucha historia. Hoy, muchas personas hablan guaraní y español. Aprender sobre el cuerpo, las máquinas y las lenguas nos muestra un mundo diverso.', '¿Qué hace el corazón?', '["Piensa y siente","Bombea sangre","Mueve los músculos","Habla guaraní"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"O coração bombeia sangue pelo corpo. O cérebro pensa e sente, os músculos movem, e o guaraní é uma língua.","options":["Piensa y siente","Bombea sangre","Mueve los músculos","Habla guaraní"],"prompt":"¿Qué hace el corazón?"},{"answer_index":2,"explanation_pt_br":"A homeostase é o equilíbrio interno do corpo para funcionar bem. Não é máquina, idioma nem computador.","options":["Una máquina","Un idioma","Un equilibrio del cuerpo","Un tipo de computadora"],"prompt":"¿Qué es la homeostasis?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-9c8daef65ec5', 'es', 'A1', 'Voy a aprender español', 'Hola, amigo. Mañana voy a estudiar español en una escuela nueva. Mi amiga Ana va a venir conmigo. Ella quiere hablar con los profesores. Nosotros vamos a aprender muchas palabras. Después de la clase, vamos a tomar café en un bar cerca de la escuela. El bar es pequeño pero muy bonito. Los fines de semana, yo voy a practicar en casa con videos. Ana va a escuchar música en español. Nosotros vamos a ver películas también. ¿Y tú? ¿Qué vas a hacer?', '¿Qué va a hacer Ana mañana?', '["Estudiar español","Cocinar comida","Viajar a Brasil","Trabajar en un bar"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"O texto diz: ''Mañana voy a estudiar español'' e ''Mi amiga Ana va a venir conmigo''. Portanto, Ana vai estudar espanhol.","options":["Estudiar español","Cocinar comida","Viajar a Brasil","Trabajar en un bar"],"prompt":"¿Qué va a hacer Ana mañana?"},{"answer_index":1,"explanation_pt_br":"O texto diz: ''vamos a tomar café en un bar cerca de la escuela''.","options":["En la escuela","En un bar","En casa","En un cine"],"prompt":"¿Dónde van a tomar café después de la clase?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-1081d6aac252', 'es', 'A1', 'El restaurante: género y número', '¡Hola! Hoy aprendemos sobre el género y el número en español. En esta lección, veremos cómo los sustantivos pueden ser masculinos o femeninos y singulares o plurales. Por ejemplo, ''el libro'' es masculino y ''la mesa'' es femenina. Para hacer el plural, normalmente añadimos ''-s'' o ''-es''. Así, ''un libro'' se convierte en ''unos libros'', y ''una flor'' en ''unas flores''. Es esencial usar el artículo correcto: ''el'' o ''los'' para masculino, ''la'' o ''las'' para femenino.

En un restaurante, observamos muchos ejemplos. ''El menú'' es masculino, ''la cuenta'' es femenina. ''Los platos'' son masculinos plurales, y ''las sillas'' son femeninas plurales. Para referirnos a cosas de manera indefinida, usamos ''un'' o ''una'' para el singular, y ''unos'' o ''unas'' para el plural. Por ejemplo, ''un tenedor'' y ''unos tenedores''.

Ahora, practiquemos con algunas palabras. Recuerda: en español, el artículo debe concordar en género y número con el sustantivo. ¡Vamos a hacer preguntas!', '¿Cuál es la forma plural correcta de ''la silla''?', '["las sillas","los sillas","las sillos","los sillos"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"A forma plural de ''la silla'' é ''las sillas'', porque ''silla'' é feminina e acrescentamos ''-s''.","options":["las sillas","los sillas","las sillos","los sillos"],"prompt":"¿Cuál es la forma plural correcta de ''la silla''?"},{"answer_index":0,"explanation_pt_br":"''Mesa'' é um substantivo feminino, então o artigo definido correto é ''la''.","options":["la","el","los","las"],"prompt":"¿Cuál es el artículo correcto para ''mesa''?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-3bb8d06c7a30', 'es', 'A1', 'Mi Rutina Diaria', 'Hola, me llamo Carlos y soy de Brasil. Todos los días me levanto a las seis de la mañana. Después, me ducho y desayuno. Normalmente como pan con café. A las siete y media salgo de casa y voy al trabajo en autobús. Trabajo en una oficina en el centro. A la una almuerzo con mis compañeros. Por la tarde, termino a las cinco y vuelvo a casa. Ceno con mi familia y veo la televisión. A veces hago ejercicio o leo un libro. Me acuesto a las diez. Los fines de semana es diferente: me levanto más tarde y salgo con mis amigos. Ellos son muy divertidos.', '¿A qué hora se levanta Carlos normalmente?', '["A las seis","A las siete","A las ocho","A las nueve"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"No texto, Carlos diz: ''Todos los días me levanto a las seis de la mañana.'' Portanto, a resposta correta é ''A las seis''.","options":["A las seis","A las siete","A las ocho","A las nueve"],"prompt":"¿A qué hora se levanta Carlos normalmente?"},{"answer_index":0,"explanation_pt_br":"O texto diz: ''Ceno con mi familia y veo la televisión.'' Então, depois de jantar, ele vê TV. As outras opções não são mencionadas após a ceia.","options":["Ve la televisión","Trabaja","Se ducha","Desayuna"],"prompt":"¿Qué hace Carlos después de cenar?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-413b3420b34f', 'es', 'A1', '¿Qué hay en mi casa?', 'Hola, me llamo María. Tengo una casa pequeña. En mi casa hay tres habitaciones: un salón, una cocina y un dormitorio. En el salón hay un sofá, una mesa y una televisión. La televisión es muy grande. En la cocina hay una nevera y una estufa. La nevera está llena de frutas y verduras. Mi dormitorio está limpio y ordenado. Hay una cama, un armario y una lámpara. La lámpara es bonita y está sobre la mesita de noche. Mi casa está cerca de un parque y hay muchos árboles. Me gusta mi casa porque es cómoda y está en un lugar tranquilo.', '¿Qué hay en el dormitorio de María?', '["Hay una cama, un armario y una lámpara.","Hay un sofá, una mesa y una televisión.","Hay una nevera y una estufa.","Hay muchos árboles."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"No texto, María diz: ''Hay una cama, un armario y una lámpara.'' no dormitório.","options":["Hay una cama, un armario y una lámpara.","Hay un sofá, una mesa y una televisión.","Hay una nevera y una estufa.","Hay muchos árboles."],"prompt":"¿Qué hay en el dormitorio de María?"},{"answer_index":1,"explanation_pt_br":"María diz: ''Mi dormitorio está limpio y ordenado.'' Então está ordenado.","options":["Está sucio.","Está ordenado.","Está vacío.","Está lejos."],"prompt":"¿Cómo está el dormitorio de María?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-f5d2be88f95b', 'es', 'A1', 'Mi día con tener, ir y hacer', 'Hoy es sábado. Por la mañana, yo tengo hambre y voy a la cocina. Mi madre hace el desayuno: pan, café y frutas. Después, mi padre y yo vamos al parque para hacer ejercicio. Correos y caminamos. A las doce, tengo sed y bebo agua. Por la tarde, mi hermana y yo hacemos la tarea en casa. A las cinco, voy a la casa de mi amigo. Él tiene un perro muy grande. Hacemos videojuegos. Por la noche, todos tenemos sueño. Mañana, vamos a la playa y hacemos una barbacoa. ¡Qué semana!', '¿Qué tiene la madre para el desayuno?', '["pan, café y frutas","arroz, carne y ensalada","tortilla y jugo","sopa y pan"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"No texto, a mãe faz o desayuno: ''pan, café y frutas''.","options":["pan, café y frutas","arroz, carne y ensalada","tortilla y jugo","sopa y pan"],"prompt":"¿Qué tiene la madre para el desayuno?"},{"answer_index":1,"explanation_pt_br":"O texto diz: ''mi padre y yo vamos al parque para hacer ejercicio''.","options":["a la escuela","al parque","al mercado","al cine"],"prompt":"¿Adónde van el padre y yo por la mañana?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-27e95e1aced4', 'es', 'A1', 'Mi casa y este objeto', 'Hola, soy Ana. Esta es mi casa. Este es mi dormitorio y esa es mi cocina. Estos son mis libros y esas son mis llaves. Este teléfono es mío, pero esa computadora es de mi hermano. Esos zapatos son de mi madre. ¿Y tú? ¿Dónde está tu casa? ¿Este es tu libro o ese es tu libro? Los posesivos y demostrativos nos ayudan a hablar de las cosas y personas.', '¿Qué es de Ana?', '["La casa","La computadora","Los zapatos","Las llaves"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"No texto, Ana diz ''Esta es mi casa'', então a casa é dela.","options":["La casa","La computadora","Los zapatos","Las llaves"],"prompt":"¿Qué es de Ana?"},{"answer_index":1,"explanation_pt_br":"O texto diz ''esa computadora es de mi hermano'', portanto é do irmão de Ana.","options":["De Ana","Del hermano de Ana","De la madre de Ana","De nadie"],"prompt":"¿De quién es la computadora?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-9405dbf706d4', 'es', 'A1', 'En la clase', 'Hola, amigos. Hoy hablamos de la clase de español. La clase es un lugar para aprender. El profesor explica la lección. Los estudiantes escuchan y preguntan. En la clase, nosotros usamos libros, cuadernos y bolígrafos. La pizarra está en la pared. La mesa y la silla son para trabajar. El diccionario ayuda con las palabras. La clase es interesante y divertida.

En la clase hay muchas cosas. ¿Qué ves? Veo una bandera y un mapa. La ventana está abierta y la puerta está cerrada. Los estudiantes hablan en español. Ellos practican la conversación. También cantan canciones y juegan juegos. La clase termina a las doce. Después, los estudiantes van a casa.

La clase es un buen lugar para hacer amigos. Todos ayudan y comparten. Aprender español es una aventura. ¡Bienvenidos a la clase!', '¿Qué es la clase?', '["un lugar para aprender","un lugar para comer","un lugar para jugar fútbol","un lugar para dormir"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"O texto diz: ''La clase es un lugar para aprender.'' (A sala de aula é um lugar para aprender.)","options":["un lugar para aprender","un lugar para comer","un lugar para jugar fútbol","un lugar para dormir"],"prompt":"¿Qué es la clase?"},{"answer_index":0,"explanation_pt_br":"O texto diz: ''Los estudiantes escuchan y preguntan.'' (Os estudantes escutam e perguntam.)","options":["escuchan y preguntan","cocinan y comen","corren y saltan","duermen y sueñan"],"prompt":"¿Qué hacen los estudiantes en la clase?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-b15322434526', 'es', 'A1', 'Mis planes para el futuro', 'Hola, me llamo Carlos y soy de Brasil. Este fin de semana voy a visitar a mi abuela. Ella vive en una casa pequeña cerca del mar. Voy a viajar en autobús el sábado por la mañana. También voy a comprar flores para mi abuela. Ella va a cocinar una cena especial. Mi hermana va a venir conmigo. Ella va a traer un pastel de chocolate.

El domingo, mi hermano y yo vamos a jugar al fútbol en el parque. Vamos a invitar a nuestros amigos. Después del partido, vamos a comer pizza en un restaurante. Por la noche, todos vamos a ver una película en casa. Vamos a comer palomitas. Mañana, voy a estudiar español con mis compañeros. Voy a practicar la conjugación de los verbos. Vamos a hablar mucho en clase. Me gusta aprender español.', '¿Qué va a hacer Carlos el sábado por la mañana?', '["Va a viajar en autobús.","Va a jugar al fútbol.","Va a ver una película.","Va a estudiar español."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"No texto, Carlos diz: ''Voy a viajar en autobús el sábado por la mañana.'' Portanto, a resposta correta é ''Va a viajar en autobús''.","options":["Va a viajar en autobús.","Va a jugar al fútbol.","Va a ver una película.","Va a estudiar español."],"prompt":"¿Qué va a hacer Carlos el sábado por la mañana?"},{"answer_index":0,"explanation_pt_br":"Carlos menciona: ''Mi hermana va a venir conmigo. Ella va a traer un pastel de chocolate.'' Então, a irmã dele vai trazer o bolo.","options":["La hermana de Carlos.","El hermano de Carlos.","La abuela de Carlos.","Un amigo de Carlos."],"prompt":"¿Quién va a traer un pastel de chocolate?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-03a35d90c2f4', 'es', 'A1', 'Un día en la oficina', 'Hoy es lunes. Ana trabaja en una oficina. Ella tiene un computador, un teléfono y unos libros. Los hombres y las mujeres trabajan juntos. Los teléfonos son importantes para el trabajo. Ana habla con un cliente. El cliente es muy amable. Los clientes y las clientas son importantes para la empresa.

En la oficina, hay unas ventanas y unas puertas. Las ventanas son grandes. Las puertas son blancas. Ana come un sándwich y bebe un café. El café es bueno. Los sándwiches son ricos. Ana está feliz en su trabajo.

La semana es larga, pero el trabajo es interesante. Ana aprende cada día. Ella piensa: "La oficina es mi segundo hogar."', '¿Cuál es el artículo correcto para la palabra ''computador''?', '["el computador","la computador","los computador","las computador"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"A palavra ''computador'' é masculina em espanhol, então o artigo correto é ''el''.","options":["el computador","la computador","los computador","las computador"],"prompt":"¿Cuál es el artículo correcto para la palabra ''computador''?"},{"answer_index":0,"explanation_pt_br":"O plural de ''la ventana'' é ''las ventanas'' porque é feminino e plural.","options":["las ventanas","los ventanas","la ventanas","el ventanas"],"prompt":"¿Cuál es la forma plural correcta de ''la ventana''?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-c7202046c790', 'es', 'A1', 'Mi día típico', 'Cada mañana, yo me despierto a las siete. Después, yo me levanto y me ducho. Mi esposa hace el desayuno: café, pan y frutas. Nosotros comemos juntos y hablamos de nuestros planes.

A las ocho, yo salgo de casa y voy al trabajo. Mi esposa trabaja en un hospital. Ella es enfermera. A veces, ella viene a casa al mediodía y almuerza conmigo. Yo siempre almuerzo en la oficina con mis colegas.

Por la tarde, yo regreso a casa a las seis. Mi esposa y yo preparamos la cena. Después, nosotros vemos la televisión o leemos un libro. A las diez, yo me acuesto y duermo. Mi esposa duerme más tarde.', '¿Qué hace la esposa cada mañana?', '["Ella hace el desayuno.","Ella trabaja en un hospital.","Ella ve la televisión.","Ella lee un libro."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"O texto diz: ''Mi esposa hace el desayuno: café, pan y frutas.'' Portanto, a opção correta é ''Ella hace el desayuno.''","options":["Ella hace el desayuno.","Ella trabaja en un hospital.","Ella ve la televisión.","Ella lee un libro."],"prompt":"¿Qué hace la esposa cada mañana?"},{"answer_index":0,"explanation_pt_br":"O texto diz: ''Yo siempre almuerzo en la oficina con mis colegas.'' E antes: ''Ella viene a casa al mediodía y almuerza comigo.'' Mas a pergunta é sobre o esposo, que almoça na oficina ao meio-dia. Portanto, ''Al mediodía''.","options":["Al mediodía","A las diez","A las ocho","A las seis"],"prompt":"¿Cuándo almuerza el esposo?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-d9dc8ed3ac84', 'es', 'A1', '¿Quién es? ¿Cómo está? ¿Qué hay?', 'En español, usamos tres verbos para describir personas, lugares y cosas: SER, ESTAR y HAY.

SER describe características permanentes. Por ejemplo: "Yo soy Ana". "La casa es grande".

ESTAR describe estados temporales o ubicación. Por ejemplo: "Yo estoy contento". "El libro está en la mesa".

HAY significa "existe" o "hay". Se usa para hablar de la existencia de algo. Por ejemplo: "Hay un perro en el parque". "En la clase hay estudiantes".

Es importante practicar estos verbos para hablar bien en español.', '¿Cuál es la forma correcta para hablar de una característica permanente?', '["Yo estoy alto.","Yo soy alto.","Hay un coche.","El coche está en la calle."]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"SER é usado para características permanentes, como altura. ''Yo soy alto'' é correto.","options":["Yo estoy alto.","Yo soy alto.","Hay un coche.","El coche está en la calle."],"prompt":"¿Cuál es la forma correcta para hablar de una característica permanente?"},{"answer_index":2,"explanation_pt_br":"ESTAR é usado para localização temporária: ''La silla está en la cocina''.","options":["La silla es en la cocina.","La silla hay en la cocina.","La silla está en la cocina.","La silla ser en la cocina."],"prompt":"¿Cuál es la forma correcta para hablar de una ubicación temporal?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-909ff4e72b91', 'es', 'A1', 'Mis planes para el fin de semana', 'Hola, soy Ana. Tengo veinticinco años y vivo en São Paulo. Trabajo en una oficina y estudio español por la noche. Este fin de semana tengo muchos planes. El sábado, voy a visitar a mi abuela. Ella hace una comida deliciosa. Después, voy a ir al parque con mis amigos. Nosotros hacemos un picnic allí. El domingo, voy a hacer mis tareas y también voy a ir al cine. Me gusta ver películas en español. ¿Y tú? ¿Qué vas a hacer este fin de semana? Tienes tiempo libre o tienes que trabajar?', '¿Qué hace Ana el sábado?', '["Va al cine.","Hace un picnic con amigos.","Visita a su abuela.","Trabaja en la oficina."]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"No texto, Ana diz: ''El sábado, voy a visitar a mi abuela.'' Então a resposta correta é ''Visita a su abuela.''","options":["Va al cine.","Hace un picnic con amigos.","Visita a su abuela.","Trabaja en la oficina."],"prompt":"¿Qué hace Ana el sábado?"},{"answer_index":0,"explanation_pt_br":"No texto, Ana afirma: ''Este fin de semana tengo muchos planes.'' Portanto, a resposta correta é ''Sí, tiene muchos planes.''","options":["Sí, tiene muchos planes.","No, no tiene planes.","Solo tiene planes para el domingo.","No sabe."],"prompt":"¿Ana tiene planes para el fin de semana?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-5048328b91be', 'es', 'A1', 'Me gusta el español', '¡Hola! ¿Te gusta aprender español? A mí me gusta mucho. El español es una lengua bonita y útil. En Brasil, muchas personas quieren hablar español. ¿Por qué? Porque Brasil tiene muchos países vecinos que hablan español.

A mí me gusta la música en español. También me gustan las películas y las comidas de España y de México. ¿Y a ti? ¿Te gusta el cine? ¿Te gusta la comida mexicana? Es muy importante practicar todos los días. ¡Vamos a aprender juntos!', '¿Qué le gusta a la persona?', '["Aprender español.","Viajar a Brasil.","Cocinar comida brasileña.","Hablar inglés."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"A pessoa diz ''A mí me gusta mucho'' depois de ''¿Te gusta aprender español?'', então ela gosta de aprender espanhol.","options":["Aprender español.","Viajar a Brasil.","Cocinar comida brasileña.","Hablar inglés."],"prompt":"¿Qué le gusta a la persona?"},{"answer_index":0,"explanation_pt_br":"A pessoa diz ''A mí me gusta la música en español'', indicando que ela também gosta de música em espanhol.","options":["La música en español.","El fútbol.","La playa.","Los libros de historia."],"prompt":"¿Qué le gusta también a la persona?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-b0b563c12a02', 'es', 'A1', 'Me, te, se... ¡Nosotros nos cuidamos!', 'Cada mañana, yo me levanto temprano. Mi hermana se ducha y se viste rápido. Mis padres se preparan el café. Nosotros nos sentamos a la mesa y comemos juntos. Ellos se sienten felices por la familia. ¿Y tú? Tú te sientas con nosotros. Todos nos miramos y sonreímos. Practicamos los pronombres reflexivos: me, te, se, nos, os, se. Son importantes para hablar de rutinas y emociones. Con la práctica, tú te sientes más seguro. ¡Vamos a aprender!', '¿Qué pronombre reflexivo usamos para ''yo''?', '["me","te","se","nos"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Para ''yo'', usamos ''me''. Exemplo: ''Yo me levanto''.","options":["me","te","se","nos"],"prompt":"¿Qué pronombre reflexivo usamos para ''yo''?"},{"answer_index":0,"explanation_pt_br":"Para ''ellos'' e ''ellas'', usamos ''se''. Exemplo: ''Ellos se sienten felices''.","options":["se","os","nos","te"],"prompt":"¿Qué pronombre reflexivo usamos para ''ellos''?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-b522ecaed962', 'es', 'A1', '¿De dónde eres?', 'Hola, soy Ana. Soy de Brasil, pero vivo en España. Mi amigo Carlos es de México. Él es estudiante. Hoy, en la clase, hablamos de nacionalidades. Yo soy brasileña, Carlos es mexicano y nuestra profesora es española. Ella es de Madrid. También hay estudiantes de Argentina, Chile y Colombia. Todos somos de América Latina, pero ahora vivimos en Europa. La profesora pregunta: "¿De dónde eres, Ana?" Yo respondo: "Soy de Brasil". La profesora pregunta: "¿Y tú, Carlos?" Carlos dice: "Soy de México". La profesora está contenta. Ella dice: "Muy bien. Ahora, todos saben de dónde son sus compañeros."', '¿De dónde es Ana?', '["Brasil","España","México","Argentina"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"O texto diz: ''Soy de Brasil''.","options":["Brasil","España","México","Argentina"],"prompt":"¿De dónde es Ana?"},{"answer_index":1,"explanation_pt_br":"O texto diz: ''Mi amigo Carlos es de México.''","options":["Ana","Carlos","La profesora","Los estudiantes de Chile"],"prompt":"¿Quién es de México?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a1-4b425c5842f4', 'es', 'A1', 'Voy a aprender español', 'Hola, amigos. Hoy vamos a hablar de planes y el futuro. En español, usamos “ir a + infinitivo”. Es muy fácil y útil. Por ejemplo: “Voy a estudiar español.” “Ella va a viajar a Brasil.” “Nosotros vamos a comer pizza.”

Primero, conjugamos el verbo “ir”. Yo voy, tú vas, él/ella/usted va, nosotros/as vamos, vosotros/as vais, ellos/ellas/ustedes van. Después, añadimos la letra “a” y el infinitivo del verbo. Por ejemplo: “Tú vas a trabajar.” “Ellos van a nadar en el mar.”

Es importante para hablar de planes y sueños. ¡Practiquemos!', '¿Qué vamos a hacer?', '["Vamos a viajar a Brasil.","Él va a comer.","Yo voy a estudiar.","Ella va a bailar."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"A pergunta ''¿Qué vamos a hacer?'' pede uma ação futura com ''nosotros''. A opção correta é ''Vamos a viajar a Brasil'', usando ''vamos a + infinitivo''.","options":["Vamos a viajar a Brasil.","Él va a comer.","Yo voy a estudiar.","Ella va a bailar."],"prompt":"¿Qué vamos a hacer?"},{"answer_index":0,"explanation_pt_br":"A forma correta é ''Ella va a trabajar'' porque usamos ''va'' para ela (terceira pessoa singular) e ''a + infinitivo''.","options":["Ella va a trabajar.","Ella vas a trabajar.","Ella va a trabaja.","Ella va trabajar."],"prompt":"¿Cómo se dice ''She is going to work'' em espanhol?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-78747d60a330', 'fr', 'A1', 'Les articles et les objets', 'Dans cette leçon, nous allons découvrir les articles définis et indéfinis en français. Les articles définis sont : le, la, les. Les articles indéfinis sont : un, une, des. Ils s''accordent avec le genre et le nombre du nom.

Par exemple, pour les objets du quotidien : un livre, une table, des chaises. On utilise “un” pour un nom masculin singulier, “une” pour un nom féminin singulier, et “des” pour le pluriel. Pour dire “le livre” ou “la table”, on utilise les articles définis “le” et “la”.

Maintenant, essayez de choisir le bon article pour chaque phrase. Bonne chance !', 'Complétez avec l''article correct : ____ chien est noir.', '["un","une","des","le"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"\"Chien\" é um substantivo masculino singular, então usamos \"un\" para artigo indefinido.","options":["un","une","des","le"],"prompt":"Complétez avec l''article correct : ____ chien est noir."},{"answer_index":1,"explanation_pt_br":"\"Pommes\" é plural, então usamos \"les\" (definido) ou \"des\" (indefinido). Aqui, como é definido, usamos \"les\".","options":["la","les","une","des"],"prompt":"Complétez avec l''article correct : ____ pommes sont rouges."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-df6d5a087406', 'fr', 'A1', 'Les verbes essentiels', 'Bonjour ! Aujourd''hui, nous allons apprendre quatre verbes très importants en français : être, avoir, aller et faire. Ces verbes sont utilisés tous les jours.

Je suis brésilien. Tu es étudiant. Il est content. Nous sommes amis. Vous êtes professeurs. Ils sont fatigués.

J''ai un livre. Tu as une sœur. Elle a une voiture. Nous avons faim. Vous avez soif. Ils ont des idées.

Je vais à l''école. Tu vas au marché. Il va à Paris. Nous allons au cinéma. Vous allez bien. Elles vont au travail.

Je fais du sport. Tu fais un gâteau. Elle fait ses devoirs. Nous faisons un voyage. Vous faites attention. Ils font du bruit.

Utilisez ces verbes pour parler de vous et des autres. Pratiquez chaque jour !', 'Complétez : Je ______ étudiant.', '["suis","as","va","fais"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Para o sujeito ''je'', a forma correta do verbo ''être'' é ''suis''.","options":["suis","as","va","fais"],"prompt":"Complétez : Je ______ étudiant."},{"answer_index":2,"explanation_pt_br":"Para ''nous'', o verbo ''aller'' é conjugado como ''allons''.","options":["sommes","avons","allons","faisons"],"prompt":"Complétez : Nous ______ au Brésil."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-ad8ba87d5e84', 'fr', 'A1', 'Les verbes du quotidien', 'Aujourd''hui, nous parlons des verbes du premier groupe et de quelques verbes fréquents. Par exemple, « parler », « manger », « aimer » sont des verbes en -er. On les utilise beaucoup. « Être » et « avoir » sont aussi très importants. Ils ne sont pas en -er, mais on les utilise tous les jours.

Au présent, les verbes en -er se conjuguent avec les terminaisons : -e, -es, -e, -ons, -ez, -ent. Par exemple, avec « parler » : je parle, tu parles, il parle, nous parlons, vous parlez, ils parlent. Attention aux terminaisons !

Imaginez une journée. Je me lève, je mange, je travaille, je parle avec des amis. Vous aimez cette routine ? Moi, j''aime beaucoup !', 'Quelle est la bonne conjugaison de « parler » avec « nous » ?', '["nous parlez","nous parlons","nous parlent","nous parles"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"A terminação para ''nous'' com verbos em -er é ''-ons'', então ''nous parlons''.","options":["nous parlez","nous parlons","nous parlent","nous parles"],"prompt":"Quelle est la bonne conjugaison de « parler » avec « nous » ?"},{"answer_index":2,"explanation_pt_br":"''Être'' é um verbo irregular, não termina em -er. Os outros são do primeiro grupo.","options":["aimer","manger","être","parler"],"prompt":"Quel verbe n''est pas un verbe en -er ?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-0881b7e76c2d', 'fr', 'A1', 'La négation : ne...pas', 'Pour faire une phrase négative en français, on utilise « ne...pas ». Le mot « ne » se place avant le verbe, et « pas » se place après le verbe. Par exemple : « Je ne mange pas de pizza. » C''est simple !

Quand le verbe commence par une voyelle, « ne » devient « n'' » : « Je n''aime pas le café. » Attention ! Dans une phrase négative, on utilise souvent « de » au lieu de « un », « une » ou « des ». Par exemple : « Je n''ai pas de voiture. »

La négation est importante pour parler de ce qu''on n''aime pas, de ce qu''on ne fait pas, ou de ce qui n''existe pas. Avec la négation, vous pouvez exprimer vos préférences et vos besoins. Continuez à pratiquer !', 'Comment dit-on « I don''t speak French » en français ?', '["Je parle ne français pas.","Je ne parle pas français.","Je ne parle français pas.","Je parle pas français."]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"A ordem correta é: sujeito + ne + verbo + pas. Portanto, ''Je ne parle pas français'' é a forma correta.","options":["Je parle ne français pas.","Je ne parle pas français.","Je ne parle français pas.","Je parle pas français."],"prompt":"Comment dit-on « I don''t speak French » en français ?"},{"answer_index":0,"explanation_pt_br":"Com verbo começando com vogal, ''ne'' vira ''n''''. E ''pas'' vem depois do verbo. Assim: ''Nous n''aimons pas le chocolat.''","options":["Nous n''aimons pas le chocolat.","Nous ne aimons pas le chocolat.","Nous n''aimons le chocolat pas.","Nous aimons ne pas le chocolat."],"prompt":"Qual é a forma negativa de ''Nous aimons le chocolat''?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-3c6ec2b24b60', 'fr', 'A1', 'Questions de base', 'Aujourd''hui, nous apprenons à poser des questions simples en français. Les questions sont importantes pour connaître les gens et le monde. Par exemple, vous pouvez demander « Qui est-ce ? » ou « Où est le chat ? ». En français, il y a trois façons de poser une question : avec « est-ce que », avec l''inversion, ou avec l''intonation. Pour les débutants, « est-ce que » est facile et utile. On dit : « Est-ce que vous parlez français ? » ou « Est-ce que tu aimes le café ? ». Le mot « est-ce que » se place au début de la phrase affirmative. On peut aussi poser des questions avec des mots comme « qui », « où », « quand », « comment », « pourquoi ». Par exemple : « Qui est ton ami ? », « Où habites-tu ? », « Quand partons-nous ? », « Comment vas-tu ? », « Pourquoi es-tu fatigué ? ». Avec « est-ce que », on peut dire : « Où est-ce que tu habites ? » ou « Comment est-ce que tu vas ? ». Pratiquons avec deux questions. Regardez les phrases et choisissez la bonne question.', 'Choisissez la question correcte pour demander le nom d''une personne.', '["Quel est votre nom ?","Comment vous appelez-vous ?","Qui est-ce ?","Où est le nom ?"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"A pergunta correta para saber o nome de alguém é ''Comment vous appelez-vous ?'' (Como você se chama?). As outras opções são incorretas: ''Quel est votre nom ?'' não é natural em francês, ''Qui est-ce ?'' pergunta ''Quem é?'', e ''Où est le nom ?'' não faz sentido.","options":["Quel est votre nom ?","Comment vous appelez-vous ?","Qui est-ce ?","Où est le nom ?"],"prompt":"Choisissez la question correcte pour demander le nom d''une personne."},{"answer_index":1,"explanation_pt_br":"A pergunta correta para perguntar as horas é ''Quelle heure est-il ?'' (Que horas são?). As outras opções são incorretas: ''Quand'' é usado para ''quando'', ''Comment'' para ''como'', ''Où'' para ''onde''.","options":["Quand est-ce qu''il est ?","Quelle heure est-il ?","Comment est l''heure ?","Où est l''heure ?"],"prompt":"Choisissez la question correcte pour demander l''heure."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-cd0b82afa555', 'fr', 'A1', 'Les pronoms sujets et les pronoms toniques', 'En français, on utilise les pronoms sujets pour parler de qui fait l''action. Par exemple : « Je parle », « Tu manges », « Il habite à Paris ». Ces pronoms sont : je, tu, il, elle, on, nous, vous, ils, elles. On utilise aussi les pronoms toniques après une préposition comme « avec » ou « pour ». Par exemple : « avec moi », « pour toi ». Les pronoms toniques sont : moi, toi, lui, elle, nous, vous, eux, elles. Attention : on dit « avec lui » et non « avec il ». Regardez les exemples dans les questions.', 'Quel est le pronom tonique pour « il » ?', '["lui","il","le","la"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"O pronome tônico para ''il'' é ''lui'', usado após preposições, como em ''avec lui''.","options":["lui","il","le","la"],"prompt":"Quel est le pronom tonique pour « il » ?"},{"answer_index":1,"explanation_pt_br":"Após a preposição ''avec'', usa-se o pronome tônico ''lui'', não o pronome sujeito ''il''.","options":["Je parle avec il.","Je parle avec lui.","Je parle avec le.","Je parle avec la."],"prompt":"Choisissez la phrase correcte."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-a45384213cb7', 'fr', 'A1', 'Mes affaires et ces objets', 'Salut ! Je m''appelle Marc. Aujourd''hui, je montre mes affaires à mon ami Paul. Voici mon sac. Il est noir et petit. Ce sac est pratique pour mes livres. J''aime beaucoup ce sac.

Maintenant, je montre mes autres objets. Ce sont mes clés. Elles sont sur la table. Ces clés sont importantes pour ma maison. Et voici mon téléphone. Ce téléphone est nouveau. Je l''utilise tous les jours.

Paul me dit : « Tes affaires sont intéressantes ! » Je réponds : « Merci ! Ces objets sont utiles. » Nous parlons de nos objets préférés.', 'Quel objet est noir et petit ?', '["Le sac","Les clés","Le téléphone","La table"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"No texto, Marc diz: ''Voici mon sac. Il est noir et petit.'' Portanto, o objeto preto e pequeno é o sac.","options":["Le sac","Les clés","Le téléphone","La table"],"prompt":"Quel objet est noir et petit ?"},{"answer_index":1,"explanation_pt_br":"O texto afirma: ''Elles sont sur la table.'' Portanto, as chaves estão sobre a mesa.","options":["Dans le sac","Sur la table","Dans la maison","Avec le téléphone"],"prompt":"Où sont les clés ?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-74b46f5c2ea9', 'fr', 'A1', 'Où et Quand ? Les prépositions de lieu et de temps', 'Bonjour ! Aujourd''hui, nous apprenons les prépositions de lieu et de temps en français. C''est très important pour parler de votre journée.

Pour le lieu, nous utilisons « à » pour les villes : « Je suis à Paris. » Pour les pays, nous utilisons « en » pour les pays féminins (la France, l''Italie) et « au » pour les pays masculins (le Brésil, le Japon). Par exemple : « J''habite en France. » et « Je vais au Brésil. »

Pour le temps, nous utilisons « à » pour les heures : « Je mange à midi. » Nous utilisons « en » pour les mois, les saisons (sauf le printemps) et les années : « En janvier, il fait froid. » Nous utilisons « au » pour le printemps : « Au printemps, il fait beau. » Nous utilisons « le » pour les jours : « Le lundi, je travaille. »', 'Complétez : Je vais ___ Brésil.', '["à","en","au","aux"]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"Usamos ''au'' com países masculinos, como o Brasil.","options":["à","en","au","aux"],"prompt":"Complétez : Je vais ___ Brésil."},{"answer_index":0,"explanation_pt_br":"Usamos ''à'' com horas.","options":["à","en","au","le"],"prompt":"Complétez : J''arrive ___ 14 heures."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-850f3960e89e', 'fr', 'A1', 'Les partitifs : du, de la, des', 'Bonjour ! Aujourd''hui, nous allons parler de la nourriture et des boissons. Pour dire "some" en français, on utilise des petits mots : du, de la, des. Par exemple, "du pain" (some bread), "de la confiture" (some jam), "des œufs" (some eggs). On utilise "du" pour les mots masculins, "de la" pour les mots féminins, et "des" pour les pluriels. Par exemple, "Je mange du fromage" (I eat some cheese). "Elle boit de l''eau" (She drinks some water). Attention : avec "de l''" pour les voyelles. Dans la vie quotidienne, on demande : "Tu veux du café ?" (Do you want some coffee?). Répondre : "Oui, je veux du thé."', 'Complétez : Je voudrais ___ pain, s''il vous plaît.', '["du","de la","des","de l''"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Porque ''pain'' é masculino, usamos ''du''.","options":["du","de la","des","de l''"],"prompt":"Complétez : Je voudrais ___ pain, s''il vous plaît."},{"answer_index":1,"explanation_pt_br":"Porque ''salade'' é feminino, usamos ''de la''.","options":["du","de la","des","de l''"],"prompt":"Complétez : Elle achète ___ salade."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-40b1b071d85f', 'fr', 'A1', 'Le futur proche : prochainement !', 'Aujourd''hui, nous apprenons le futur proche. Pour parler du futur proche, on utilise ''aller'' + un infinitif. Par exemple, ''Je vais manger'' ou ''Tu vas dormir''. C''est très utile pour dire ce que l''on va faire bientôt.

Demain, je vais voyager à Paris. Il va faire beau. Nous allons visiter le musée du Louvre. Vous allez aimer la ville. Ils vont acheter des souvenirs. Après, nous allons manger une crêpe. Ce sera délicieux !

Ce soir, Marie va regarder un film. Pierre va écouter de la musique. Nous allons danser ensemble. Vous allez vous amuser. Ils vont dormir tard. Et toi, tu vas faire quoi ?', 'Qu''est-ce que je vais faire demain ?', '["Je vais manger.","Je vais voyager à Paris.","Tu vas dormir.","Nous allons danser."]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"O texto diz: ''Demain, je vais voyager à Paris.'' Portanto, a resposta correta é ''Je vais voyager à Paris.''","options":["Je vais manger.","Je vais voyager à Paris.","Tu vas dormir.","Nous allons danser."],"prompt":"Qu''est-ce que je vais faire demain ?"},{"answer_index":0,"explanation_pt_br":"O texto diz: ''Ce soir, Marie va regarder un film.'' Portanto, a resposta correta é ''Marie va regarder un film.''","options":["Marie va regarder un film.","Marie va écouter de la musique.","Marie va dormir tard.","Marie va acheter un souvenir."],"prompt":"Qu''est-ce que Marie va faire ce soir ?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-e657d1e74bb8', 'fr', 'A1', 'Le genre et le nombre', 'En français, les noms ont un genre : masculin ou féminin. Par exemple, « le livre » est masculin et « la table » est féminin. Pour former le pluriel, on ajoute souvent un « s » : « les livres ». Les articles changent avec le genre et le nombre : « un » et « une » pour le singulier, « des » pour le pluriel. Observez ces phrases : « Le chat est petit. » (masculin singulier) ; « La fleur est belle. » (féminin singulier) ; « Les chats sont petits. » (pluriel). Attention, il y a des exceptions : « un œil » devient « des yeux ». Pratiquons !', 'Complétez : « ____ chaise est confortable. »', '["Le","La","Les","Un"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"''chaise'' é um substantivo feminino, então usamos o artigo definido feminino ''la''.","options":["Le","La","Les","Un"],"prompt":"Complétez : « ____ chaise est confortable. »"},{"answer_index":2,"explanation_pt_br":"''enfants'' é plural, então usamos o artigo definido plural ''les''.","options":["Le","La","Les","Des"],"prompt":"Complétez : « ____ enfants jouent dans le jardin. »"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-0c68c1cfd30c', 'fr', 'A1', 'Les verbes en -er au présent', 'Bonjour ! Aujourd''hui, nous apprenons les verbes en -er au présent. Ces verbes sont très importants en français. Par exemple, le verbe « parler » (falar) est un verbe en -er. Au présent, on dit : je parle, tu parles, il parle, nous parlons, vous parlez, ils parlent. C''est facile !

Maintenant, regardez les phrases : « Je travaille à Paris. » et « Nous aimons le café. » Les verbes « travailler » et « aimer » sont aussi en -er. Attention : la terminaison change avec le sujet. Par exemple, avec « je », on ajoute « e », avec « tu », « es », avec « il/elle », « e », avec « nous », « ons », avec « vous », « ez », avec « ils/elles », « ent ».

Pratiquons avec des verbes fréquents : « manger » (comer), « habiter » (morar), « écouter » (ouvir). Par exemple : « Ils habitent à Rio. » et « Tu écoutes la musique. » Ces verbes sont très utilisés dans la vie quotidienne. Alors, mémorisez-les bien !', 'Choisissez la forme correcte du verbe « parler » pour « nous ».', '["parlez","parlons","parlent","parles"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"A forma correta para ''nous'' com verbos em -er é a terminação ''-ons''. Portanto, ''nous parlons''.","options":["parlez","parlons","parlent","parles"],"prompt":"Choisissez la forme correcte du verbe « parler » pour « nous »."},{"answer_index":2,"explanation_pt_br":"Para ''il/elle'', a terminação é ''-e''. Portanto, ''Il mange une pomme'' está correto.","options":["Je manges une pomme.","Tu mange une pomme.","Il mange une pomme.","Nous mangez une pomme."],"prompt":"Quelle phrase est correcte avec le verbe « manger » ?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-cd7031ec0c9e', 'fr', 'A1', 'Les questions de base', 'Pour poser des questions simples en français, on utilise souvent « est-ce que » ou l''inversion. Par exemple : « Est-ce que tu parles français ? » ou « Parles-tu français ? ». On peut aussi utiliser l''intonation : « Tu parles français ? ». Les mots interrogatifs comme « qui », « quoi », « où », « quand », « comment », « pourquoi » aident à demander des informations précises. Par exemple : « Où est la gare ? », « Comment ça va ? ». Les questions sont essentielles pour communiquer au quotidien. En saluant quelqu''un, on demande souvent : « Comment allez-vous ? » ou « Ça va ? ». Pour connaître l''identité, on demande : « Qui êtes-vous ? ». Pour savoir le lieu, on demande : « Où habitez-vous ? ». Enfin, pour comprendre une raison, on demande : « Pourquoi ? ».', 'Quel mot interrogatif demande le lieu ?', '["Qui","Où","Quand","Pourquoi"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"Où é usado para perguntar sobre lugar, como em ''Où est la gare?''.","options":["Qui","Où","Quand","Pourquoi"],"prompt":"Quel mot interrogatif demande le lieu ?"},{"answer_index":0,"explanation_pt_br":"A expressão ''Comment ça va ?'' é a forma comum de perguntar ''Como vai?''.","options":["Comment ça va ?","Qui êtes-vous ?","Où habitez-vous ?","Pourquoi ?"],"prompt":"Comment demande-t-on ''Como vai você?'' em francês?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-c29c17b72de5', 'fr', 'A1', 'Les partitifs : du, de la, des', 'Bonjour ! Aujourd''hui, nous apprenons les partitifs. Ils expriment une quantité indéterminée. En français, on utilise « du » avec les noms masculins, « de la » avec les noms féminins, et « des » avec les pluriels. Par exemple : « Je mange du pain », « Elle boit de la limonade », « Nous achetons des fruits ». Il y a aussi « de l'' » pour les voyelles : « Je veux de l''eau ». Les partitifs sont très importants pour parler de la nourriture et des boissons. Au marché, on dit : « Je voudrais du fromage », « Donnez-moi de la salade ». Pour les quantités précises, on utilise « un » ou « une » : « Un kilo de pommes ». Alors, prêt à pratiquer ?', 'Complétez : « Je veux ______ eau. »', '["du","de la","de l''","des"]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"Usamos ''de l'''' antes de vogais ou h mudo, como em ''eau''.","options":["du","de la","de l''","des"],"prompt":"Complétez : « Je veux ______ eau. »"},{"answer_index":1,"explanation_pt_br":"''Pain'' é masculino, então usamos ''du''.","options":["Je mange de la pain.","Je mange du pain.","Je mange des pain.","Je mange de l'' pain."],"prompt":"Quelle phrase est correcte ?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-e80561ddfae0', 'fr', 'A1', 'Futur Proche : Mes Projets pour Demain', 'Bonjour ! Aujourd''hui, nous allons apprendre le futur proche. C''est très facile ! On utilise le verbe « aller » + un infinitif. Par exemple : « Je vais manger ». Ça veut dire « I am going to eat » en anglais. On l''utilise pour parler de ce qu''on va faire bientôt, comme ce soir ou demain.

Par exemple, demain matin, je vais me lever à sept heures. Ensuite, je vais prendre mon petit-déjeuner. Après, je vais aller au travail. Le soir, je vais regarder un film avec ma famille.

Et toi ? Qu''est-ce que tu vas faire demain ? Pense à tes projets et réponds aux questions !', 'Quelle phrase utilise le futur proche ?', '["Je mange une pomme.","Je vais manger une pomme.","Je mangeais une pomme.","J''ai mangé une pomme."]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"A frase ''Je vais manger'' usa o futur proche, formado com o verbo ''aller'' + infinitivo.","options":["Je mange une pomme.","Je vais manger une pomme.","Je mangeais une pomme.","J''ai mangé une pomme."],"prompt":"Quelle phrase utilise le futur proche ?"},{"answer_index":1,"explanation_pt_br":"Para expressar futuro próximo em francês, usamos o verbo ''aller'' conjugado + infinitivo: ''Il va voyager''.","options":["Il voyage.","Il va voyager.","Il voyageait.","Il a voyagé."],"prompt":"Comment dit-on « Ele vai viajar » en français ?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-f787ff5196a8', 'fr', 'A1', 'Les objets de la classe', 'Dans la classe, il y a des objets. Un livre est sur la table. Une chaise est près du bureau. Les fenêtres sont grandes. Les portes sont fermées. Le professeur parle aux élèves. Les élèves écoutent. Ils regardent les images. Ils écrivent dans les cahiers. Ils lisent des phrases. Chaque objet a un genre : masculin ou féminin. Le livre est masculin. La table est féminine. Pour parler de plusieurs objets, on ajoute un -s. Le livre devient les livres. La table devient les tables. Attention aux articles : un et une pour un objet, des pour plusieurs objets. Les articles aident à comprendre le genre et le nombre.', 'Quel article pour ''chat'' (masculin singulier) ?', '["un","une","des","le"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Para substantivos masculinos singulares, usamos ''un'' (indefinido) ou ''le'' (definido). Como a pergunta pede artigo indefinido, a resposta é ''un''.","options":["un","une","des","le"],"prompt":"Quel article pour ''chat'' (masculin singulier) ?"},{"answer_index":3,"explanation_pt_br":"Para plural indefinido, usamos ''des'', independente do gênero. Portanto, ''des fleurs''.","options":["une","un","les","des"],"prompt":"Quel article pour ''fleurs'' (féminin pluriel) ?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-7754b7869755', 'fr', 'A1', 'Les verbes essentiels', 'Les verbes être, avoir, aller et faire sont très importants en français. On les utilise souvent pour parler de soi, de ses actions et de ses projets.

Aujourd''hui, nous allons apprendre à les conjuguer au présent. Par exemple, pour parler de soi, on dit : « Je suis content » (être), « J''ai un livre » (avoir), « Je vais à l''école » (aller), « Je fais du sport » (faire).

Ces verbes sont irréguliers, mais avec de la pratique, vous allez les mémoriser. Regardez les conjugaisons :

- Être : je suis, tu es, il/elle est, nous sommes, vous êtes, ils/elles sont.
- Avoir : j''ai, tu as, il/elle a, nous avons, vous avez, ils/elles ont.
- Aller : je vais, tu vas, il/elle va, nous allons, vous allez, ils/elles vont.
- Faire : je fais, tu fais, il/elle fait, nous faisons, vous faites, ils/elles font.

Pratiquez ces verbes dans des phrases simples. Par exemple : « Nous allons au marché », « Vous faites un gâteau », « Elles sont contentes ». Avec ces verbes, vous pouvez communiquer beaucoup de choses en français !', 'Complétez la phrase : « Je ___ un chien. »', '["suis","ai","vais","fais"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"A forma correta é ''ai'', pois ''avoir'' é usado para indicar posse: ''J''ai un chien'' (Eu tenho um cachorro). ''suis'' é do verbo être (ser/estar), ''vais'' é do verbo aller (ir), e ''fais'' é do verbo faire (fazer).","options":["suis","ai","vais","fais"],"prompt":"Complétez la phrase : « Je ___ un chien. »"},{"answer_index":2,"explanation_pt_br":"A forma correta é ''allons'', do verbo aller (ir), pois a frase indica movimento: ''Nous allons à Paris'' (Nós vamos a Paris). ''sommes'' é do verbo être, ''avons'' é do verbo avoir, e ''faisons'' é do verbo faire.","options":["sommes","avons","allons","faisons"],"prompt":"Complétez la phrase : « Nous ___ à Paris. »"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-e2d69e06d836', 'fr', 'A1', 'Aujourd''hui, je parle français', 'Je m''appelle Marie. Je travaille dans un bureau à Paris. J''aime mon travail. Chaque jour, je parle avec mes collègues. Nous mangeons ensemble à midi. J''habite dans un petit appartement. Je écoute de la musique et je regarde des films. Le week-end, je danse avec mes amis. Nous jouons au football. Je visite ma famille. Elle habite à Lyon. Je voyage souvent. Je vais au marché avec ma mère. J''achète des fruits et des légumes. J''adore le fromage. Je parle portugais aussi, mais je préfère le français. Je suis contente.', 'Que fait Marie chaque jour avec ses collègues ?', '["Elle danse.","Elle mange.","Elle joue.","Elle voyage."]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"No texto, Marie diz: \"Nous mangeons ensemble à midi.\" Portanto, ela come com os colegas.","options":["Elle danse.","Elle mange.","Elle joue.","Elle voyage."],"prompt":"Que fait Marie chaque jour avec ses collègues ?"},{"answer_index":1,"explanation_pt_br":"Marie diz: \"J''habite dans un petit appartement.\" E ela trabalha em Paris, indicando que mora lá.","options":["À Lyon","À Paris","À Lisbonne","À Madrid"],"prompt":"Où habite Marie ?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-fc8b0925d0ba', 'fr', 'A1', 'La négation : ne...pas', 'Pour dire que quelque chose n''est pas vrai en français, on utilise ne...pas. Le mot ne se place avant le verbe, et pas après le verbe. Par exemple : Je ne mange pas de viande.

Au présent, on conjugue le verbe, puis on met ne avant et pas après. Avec le verbe être : Je ne suis pas brésilien. Avec le verbe avoir : Tu n''as pas de frère.

Attention : si le verbe commence par une voyelle ou un h muet, ne devient n''. Par exemple : Je n''aime pas le café.

La négation est très importante pour parler de ce qu''on n''aime pas, de ce qu''on ne fait pas, etc.', 'Choisissez la phrase correcte au négatif :
Je parle français.', '["Je ne parle pas français.","Je parle ne pas français.","Je ne parle français pas.","Je ne pas parle français."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"A forma correta é ''ne'' antes do verbo e ''pas'' depois. As outras opções têm a ordem errada.","options":["Je ne parle pas français.","Je parle ne pas français.","Je ne parle français pas.","Je ne pas parle français."],"prompt":"Choisissez la phrase correcte au négatif :\nJe parle français."},{"answer_index":0,"explanation_pt_br":"Como ''habiter'' começa com vogal, usamos ''n'''' em vez de ''ne''. A conjugação ''habitons'' está correta.","options":["Nous n''habitons pas à Paris.","Nous ne habitons pas à Paris.","Nous habitons ne pas à Paris.","Nous n''habite pas à Paris."],"prompt":"Choisissez la bonne négation pour :\nNous habitons à Paris."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-ce11f1b245a9', 'fr', 'A1', 'Questions simples en français', 'Sophie est étudiante à Paris. Elle a 20 ans. Elle parle français et anglais. Elle habite dans un petit appartement. Aujourd''hui, elle va au café avec son ami Marc. Marc demande : « Tu aimes le café ? » Sophie répond : « Oui, j''aime beaucoup le café. » Ils commandent deux cafés. Marc demande : « Tu habites où ? » Sophie répond : « J''habite près de l''université. »', 'Comment s''appelle l''étudiante ?', '["Marie","Sophie","Julie","Anna"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"O texto diz: ''Sophie est étudiante à Paris.'' Portanto, o nome da estudante é Sophie.","options":["Marie","Sophie","Julie","Anna"],"prompt":"Comment s''appelle l''étudiante ?"},{"answer_index":1,"explanation_pt_br":"O texto diz: ''elle va au café avec son ami Marc''.","options":["Ils vont au cinéma","Ils vont au café","Ils vont au parc","Ils vont à la bibliothèque"],"prompt":"Que fait Sophie et Marc ?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-d19b4967b4c1', 'fr', 'A1', 'Les pronoms sujets et les pronoms accentués', 'Les pronoms sujets sont essentiels en français. Ils remplacent le nom qui fait l''action. Par exemple : « Marie mange une pomme » devient « Elle mange une pomme ». Les pronoms sujets sont : je, tu, il, elle, on, nous, vous, ils, elles. Il sont toujours placés avant le verbe.

Les pronoms accentués (ou disjoints) sont utilisés après une préposition ou pour insister. Par exemple : « Ce livre est pour moi », « Lui, il parle bien ». Les pronoms accentués sont : moi, toi, lui, elle, soi, nous, vous, eux, elles. Ils sont souvent utilisés avec des prépositions comme « avec », « pour », « chez », ou après « et ».

Voici quelques phrases : « Je vais avec toi à la fête. » Ici, « toi » est un pronom accentué. « Ils aiment voyager, et nous aussi. » Ici, « nous » est accentué. Ces pronoms sont très utilisés dans la conversation !', 'Choisis le pronom accentué pour compléter la phrase : « Ce cadeau est pour ______ ».', '["je","moi","me","mon"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"Em francês, ''pour'' pede o pronome tônico ''moi'' (equivalente a ''mim''). ''Je'' é sujeito, ''me'' é pronome objeto direto, e ''mon'' é possessivo.","options":["je","moi","me","mon"],"prompt":"Choisis le pronom accentué pour compléter la phrase : « Ce cadeau est pour ______ »."},{"answer_index":0,"explanation_pt_br":"Substituindo ''Paul et moi'' (nós) por um pronome sujeito, usamos ''nous''. ''Ils'' é masculino plural, ''on'' é singular, e ''je'' é primeira pessoa do singular.","options":["nous","ils","on","je"],"prompt":"Choisis le pronom sujet correct pour remplacer « Paul et moi » dans la phrase : « Paul et moi ______ à la maison. »"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-8f7b64dc6474', 'fr', 'A1', 'Les prépositions de lieu et de temps', 'Bonjour ! Aujourd''hui, nous allons apprendre les prépositions de lieu et de temps : à, en, au, aux, dans, sur, sous, devant, derrière, entre.

Pour le lieu : Nous utilisons ''à'' pour les villes (Je suis à Paris), ''en'' pour les pays féminins (Je vais en France), ''au'' pour les pays masculins (Il habite au Brésil), ''aux'' pour les pays pluriels (Elle voyage aux États-Unis). Pour les objets, nous utilisons ''dans'' (Le livre est dans le sac), ''sur'' (Le chat est sur la table), ''sous'' (Le chien est sous la chaise), ''devant'' (La voiture est devant la maison), ''derrière'' (Le jardin est derrière la maison), et ''entre'' (Le café est entre la boulangerie et la banque).

Pour le temps : Nous utilisons ''à'' pour les heures (Je mange à midi), ''en'' pour les mois, les saisons et les années (Je voyage en juillet, en été, en 2024), ''au'' pour les jours de la semaine quand on parle d''un moment précis (Je travaille au lundi), mais souvent on utilise ''le'' (Je travaille le lundi). ''dans'' pour une durée future (Je pars dans deux jours).

Maintenant, regardons quelques exemples : Je suis à la maison. Le livre est sur la table. Je vais en France. Je mange à 12 heures. Je pars en hiver. Je vais au Brésil. Le chat est derrière la porte. Je vais au marché le samedi. Le restaurant est entre la banque et l''école.

Pratiquez ces prépositions avec vos amis !', 'Complétez: Je vais ___ Brésil.', '["à","en","au","aux"]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"Usamos ''au'' para países masculinos. Brasil é masculino, então ''au Brésil''.","options":["à","en","au","aux"],"prompt":"Complétez: Je vais ___ Brésil."},{"answer_index":0,"explanation_pt_br":"Usamos ''sur'' para indicar que algo está em cima de uma superfície. O gato está em cima da mesa.","options":["sur","dans","sous","devant"],"prompt":"Complétez: Le chat est ___ la table."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-f03b763870b5', 'fr', 'A1', 'Les quantités', 'Au marché, Marie achète des fruits. Elle veut un kilo de pommes, mais le vendeur dit : « Voilà un kilo de pommes. » Marie demande aussi deux cents grammes de fromage et une baguette. Elle paie avec un billet de dix euros.

Après le marché, Marie prépare une salade. Elle met de l''huile et du vinaigre. Elle ajoute aussi un peu de sel et beaucoup de poivre. Elle goûte et dit : « C''est bon ! »

Chez Marie, il y a du pain, de la confiture et du beurre pour le petit-déjeuner. Elle boit du café et mange des tartines. Elle adore les repas simples.', 'Qu''est-ce que Marie achète au marché ?', '["Un kilo de pommes.","Un litre de lait.","Une douzaine d''œufs.","Un kilo de tomates."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"O texto diz: ''Elle veut un kilo de pommes''.","options":["Un kilo de pommes.","Un litre de lait.","Une douzaine d''œufs.","Un kilo de tomates."],"prompt":"Qu''est-ce que Marie achète au marché ?"},{"answer_index":0,"explanation_pt_br":"Ela põe ''de l''huile'' e ''du vinaigre'', como descrito.","options":["De l''huile et du vinaigre.","Du sel et du sucre.","Du fromage et du jambon.","Des tomates et des concombres."],"prompt":"Que met Marie dans sa salade ?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-6c7d2a445198', 'fr', 'A1', 'Le futur proche : parler de ses projets', 'Aujourd''hui, nous allons apprendre à parler de nos projets avec le futur proche. En français, on utilise le verbe « aller » + un infinitif pour exprimer une action future proche. Par exemple : « Je vais manger » signifie que je vais manger bientôt. C''est très utile pour parler de ses activités de la journée.

Voici quelques phrases :
- Je vais travailler demain.
- Tu vas regarder un film ce soir.
- Il va acheter du pain.
- Nous allons voyager en vacances.
- Ils vont jouer au football.

Le futur proche est facile à former : il suffit de conjuguer « aller » au présent et d''ajouter l''infinitif du verbe. Par exemple : « Je vais + parler », « Elle va + danser ». Utilisez cette structure pour parler de ce que vous ferez bientôt !', 'Quelle phrase utilise le futur proche ?', '["Je vais au marché.","Je vais manger.","Je parle français.","J''aime le café."]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"A opção correta é ''Je vais manger'', pois usa ''aller'' no presente + infinitivo, formando o futur proche. As outras opções não têm essa estrutura: ''Je vais au marché'' usa ''aller'' no sentido de ir a algum lugar, e as demais não usam ''aller''.","options":["Je vais au marché.","Je vais manger.","Je parle français.","J''aime le café."],"prompt":"Quelle phrase utilise le futur proche ?"},{"answer_index":0,"explanation_pt_br":"Com o pronome ''nous'', a conjugação de ''aller'' no presente é ''allons''. As outras opções são para outras pessoas: ''allez'' (vous), ''vont'' (ils/elles), ''vas'' (tu).","options":["allons","allez","vont","vas"],"prompt":"Complete: Nous ______ chanter."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-6a4467e82268', 'fr', 'A1', 'Le genre et les articles', 'En français, le genre (masculin ou féminin) des noms est important. Chaque nom est masculin ou féminin. Pour parler d''une chose, on utilise des articles : "le" ou "un" pour les noms masculins, "la" ou "une" pour les noms féminins. Par exemple, "le livre" (masculin) et "la table" (féminin). Il faut apprendre le genre des mots avec le mot.

Il y a aussi le pluriel. Au pluriel, on utilise "les" (défini) ou "des" (indéfini) pour les deux genres. Par exemple, "les livres" et "les tables". La terminaison du nom change souvent : on ajoute un "s". Mais attention, il y a des exceptions.

Pour vous aider, il y a des indices. Beaucoup de noms qui finissent par "e" sont féminins, mais pas tous. Par exemple, "le musée" est masculin. Il faut pratiquer pour mémoriser.', 'Complétez : "____ chat" (le chat)', '["La","Le","Les","Un"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"\"Chat\" é um substantivo masculino singular, então usamos \"le\".","options":["La","Le","Les","Un"],"prompt":"Complétez : \"____ chat\" (le chat)"},{"answer_index":1,"explanation_pt_br":"\"École\" é um substantivo feminino singular, então usamos \"la\".","options":["Le","La","Les","Des"],"prompt":"Complétez : \"____ école\" (a escola)"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-7ccf0a476630', 'fr', 'A1', 'Les verbes essentiels', 'Bonjour ! Aujourd''hui, nous allons apprendre quatre verbes très importants en français : être, avoir, aller et faire. Ces verbes sont utilisés tous les jours.

D''abord, le verbe être. Je suis brésilien. Tu es fatigué. Il est content. Nous sommes étudiants. Ils sont à la maison.

Ensuite, le verbe avoir. J''ai un chat. Tu as une voiture. Elle a faim. Nous avons des amis. Ils ont vingt ans.

Puis, le verbe aller. Je vais au marché. Tu vas à l''école. Il va bien. Nous allons au cinéma. Elles vont à Paris.

Enfin, le verbe faire. Je fais du sport. Tu fais un gâteau. Elle fait ses devoirs. Nous faisons un voyage. Ils font attention.

Ces verbes sont très utiles. Pratiquez-les !', 'Quel verbe est utilisé dans la phrase : « Elle a faim. » ?', '["être","avoir","aller","faire"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"A frase ''Elle a faim'' usa o verbo ''avoir'' (ter) na terceira pessoa do singular.","options":["être","avoir","aller","faire"],"prompt":"Quel verbe est utilisé dans la phrase : « Elle a faim. » ?"},{"answer_index":2,"explanation_pt_br":"A frase pede o verbo ''aller'' (ir) conjugado na primeira pessoa do plural: ''Nous allons''.","options":["sommes","avons","allons","faisons"],"prompt":"Complétez : « Nous ______ au cinéma. »"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-b326cc545478', 'fr', 'A1', 'Les verbes en -er et les verbes fréquents', 'Marie est une étudiante brésilienne à Paris. Elle parle portugais, mais elle apprend le français. Chaque matin, elle mange une baguette et elle boit un café au lait. Elle aime beaucoup la ville. Aujourd''hui, elle visite le musée du Louvre avec son ami Lucas. Ils regardent les tableaux et ils écoutent un guide. Marie adore l''art. Elle trouve les peintures magnifiques. Après la visite, ils vont au parc. Ils parlent de leurs vacances. Marie et Lucas sont contents. Ils finissent la journée avec un dîner dans un petit restaurant.', 'Que fait Marie chaque matin ?', '["Elle mange une baguette.","Elle visite le musée.","Elle parle avec Lucas.","Elle écoute un guide."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"O texto diz: ''Chaque matin, elle mange une baguette et elle boit un café au lait.'' Portanto, a ação é comer uma baguete.","options":["Elle mange une baguette.","Elle visite le musée.","Elle parle avec Lucas.","Elle écoute un guide."],"prompt":"Que fait Marie chaque matin ?"},{"answer_index":0,"explanation_pt_br":"O texto afirma: ''elle visite le musée du Louvre avec son ami Lucas.'' Então, ambos visitam.","options":["Marie et Lucas","Marie seule","Lucas seul","Le guide"],"prompt":"Qui visite le musée du Louvre ?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-e650437b7e6f', 'fr', 'A1', 'Questions simples en français', 'Bonjour ! Aujourd''hui, nous apprenons à poser des questions simples en français. Les questions sont très importantes pour parler avec les gens. Par exemple, vous pouvez demander « Comment ça va ? » ou « Où habites-tu ? ». En français, il y a deux façons de poser une question : avec est-ce que ou avec l''inversion. Pour les débutants, est-ce que est plus facile. Par exemple : « Est-ce que tu parles français ? ». Vous pouvez aussi utiliser des mots comme qui, quoi, où, quand, pourquoi et comment. Ces mots aident à demander des informations. Par exemple : « Qui est-ce ? », « Où est la gare ? ». Avec ces questions, vous pouvez commencer une conversation. Pratiquez ces questions avec vos amis !', 'Comment demander « Où est la gare ? » en utilisant est-ce que ?', '["Où est-ce que la gare ?","Est-ce que la gare est où ?","Où est-ce que est la gare ?","Est-ce que où est la gare ?"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Em francês, quando usamos ''est-ce que'' com ''où'', a ordem correta é: Où + est-ce que + sujeito + verbo? Portanto, ''Où est-ce que la gare ?'' está correto. As outras opções não estão na ordem correta.","options":["Où est-ce que la gare ?","Est-ce que la gare est où ?","Où est-ce que est la gare ?","Est-ce que où est la gare ?"],"prompt":"Comment demander « Où est la gare ? » en utilisant est-ce que ?"},{"answer_index":1,"explanation_pt_br":"Usar ''est-ce que'' é uma forma simples de fazer pergunta: Est-ce que + sujeito + verbo. Portanto, ''Est-ce que tu parles français ?'' é a opção correta. As outras opções são corretas em francês, mas não usam ''est-ce que''.","options":["Parles-tu français ?","Est-ce que tu parles français ?","Tu parles français ?","Parles français-tu ?"],"prompt":"Qual pergunta usa ''est-ce que'' para perguntar ''Você fala francês?''"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-ffe31f475786', 'fr', 'A1', 'Mon quartier et mes objets', 'Bonjour ! Je m''appelle Marie. J''habite dans un petit quartier à Lyon. Voici mon appartement : il est petit mais confortable. Dans mon salon, il y a un canapé et une table. Ce canapé est rouge. Cette table est en bois. J''aime beaucoup mes livres. Ces livres sont sur l''étagère. Regardez ! Voici mon vélo. Ce vélo est bleu. Et voilà mes clés. Ces clés sont importantes. Dans la cuisine, j''ai des tasses. Ces tasses sont blanches. Mes voisins sont sympas. Leur jardin est joli. Et votre quartier ? Il est comment ?', 'Quel est le canapé de Marie ?', '["Il est rouge.","Il est bleu.","Il est blanc.","Il est vert."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"No texto, Marie diz: ''Ce canapé est rouge.'' Portanto, o sofá é vermelho.","options":["Il est rouge.","Il est bleu.","Il est blanc.","Il est vert."],"prompt":"Quel est le canapé de Marie ?"},{"answer_index":0,"explanation_pt_br":"No texto, Marie afirma: ''Ces clés sont importantes.'' A resposta correta é que elas são importantes.","options":["Elles sont importantes.","Elles sont petites.","Elles sont rouges.","Elles sont sur la table."],"prompt":"Quelles sont les clés de Marie ?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-e2fbf5cd5e9d', 'fr', 'A1', 'Où et Quand ?', 'Bonjour ! Aujourd''hui, nous apprenons les prépositions de lieu et de temps. En français, on utilise « à » pour les villes et les moments, « en » pour les pays et les saisons, et « au » pour les pays masculins. Par exemple, « Je suis à Paris » et « Je vais en France ». Pour le temps, on dit « à 8 heures » et « en été ». Attention : on dit « au Brésil », mais « en Italie ». Avec les mois et les années, on utilise « en » : « en janvier », « en 2024 ». Maintenant, pratiquons avec des questions !', 'Choisissez la bonne préposition : Je travaille ___ bureau.', '["à","en","au","dans"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Usamos ''à'' para lugares específicos como ''bureau''.","options":["à","en","au","dans"],"prompt":"Choisissez la bonne préposition : Je travaille ___ bureau."},{"answer_index":0,"explanation_pt_br":"Usamos ''en'' para estações (férias) e ''en'' para meses.","options":["en, en","à, à","en, au","au, en"],"prompt":"Choisissez la bonne préposition : Il part ___ vacances ___ août."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-9f54c27376f7', 'fr', 'A1', 'Les partitifs : du, de la, des', 'En français, pour parler d''une quantité indéterminée, on utilise les articles partitifs : du, de la, des. Par exemple : « Je mange du pain. » (pain masculin) et « Elle boit de la limonade. » (limonade féminin). Avec un pluriel, on utilise des : « Nous achetons des fruits. » Après une négation, on utilise de : « Je ne mange pas de pain. » Attention, on dit « de l''eau » devant une voyelle. Au marché, on demande : « Je voudrais du fromage, s''il vous plaît. » Et pour exprimer une quantité précise, on utilise des expressions comme « un kilo de », « une bouteille de ». Par exemple : « Un kilo de pommes, une bouteille de jus. » Ces expressions sont très utiles au restaurant ou au marché.', 'Quelle phrase utilise correctement un article partitif ?', '["Je voudrais du fromage.","Je voudrais le fromage.","Je voudrais de fromage.","Je voudrais des fromage."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"A forma correta é ''du fromage'' porque ''fromage'' é masculino e usamos ''du'' para quantidade indefinida. As outras opções não estão corretas: ''le'' é artigo definido, ''de'' é usado após negação e ''des'' é para plural.","options":["Je voudrais du fromage.","Je voudrais le fromage.","Je voudrais de fromage.","Je voudrais des fromage."],"prompt":"Quelle phrase utilise correctement un article partitif ?"},{"answer_index":0,"explanation_pt_br":"Após uma negação, usamos ''de'' no lugar do partitivo. Então a forma correta é ''de pain''. As outras opções são usadas em frases afirmativas.","options":["de","du","de la","des"],"prompt":"Complete : « Je ne mange pas ______ pain. »"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-e8ee644a70c3', 'fr', 'A1', 'Le futur proche', 'Le futur proche est un temps très utile en français. Il exprime une action qui va se passer bientôt. Par exemple : « Je vais manger. » Pour former le futur proche, on utilise le verbe « aller » au présent plus l''infinitif du verbe. Par exemple : « Je vais parler. »

Aujourd''hui, nous allons parler de nos projets. Demain, je vais visiter mes amis. Samedi, nous allons aller au cinéma. Ce soir, tu vas faire tes devoirs. Et vous, qu''est-ce que vous allez faire ?', 'Qu''est-ce que tu vas faire demain ?', '["Je vais manger une pizza.","Je vais à l''école.","Je vais au cinéma.","Je vais bien."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"A resposta correta usa o futur proche: ''Je vais manger'' (Eu vou comer). As outras opções não expressam uma ação futura com ''aller + infinitif''.","options":["Je vais manger une pizza.","Je vais à l''école.","Je vais au cinéma.","Je vais bien."],"prompt":"Qu''est-ce que tu vas faire demain ?"},{"answer_index":0,"explanation_pt_br":"Com ''nous'', a forma correta do verbo ''aller'' no presente é ''allons''. Portanto, ''Nous allons parler français'' (Nós vamos falar francês).","options":["allons","allez","vont","vas"],"prompt":"Complétez : Nous ______ parler français."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-c1986b138b3d', 'fr', 'A1', 'Les verbes essentiels', 'Bonjour ! Aujourd''hui, nous allons apprendre quatre verbes très importants en français : être, avoir, aller et faire. Ces verbes sont utilisés tout le temps ! Par exemple, pour parler de ton état, de tes possessions, de tes déplacements et de tes activités. Regarde ces phrases :

Je suis brésilien. Tu as un chat. Nous allons à Paris. Ils font du sport. Ce sont des exemples simples, mais très utiles.

Maintenant, écoutez une petite histoire. Marie est une étudiante. Elle a vingt ans. Elle va à l''université tous les jours. Elle fait ses devoirs le soir. Elle est très contente. Et vous ?', 'Quel verbe est utilisé pour parler d''une action quotidienne ?', '["être","avoir","aller","faire"]'::jsonb, 3, '[{"answer_index":3,"explanation_pt_br":"O verbo ''faire'' é usado para expressar atividades, como ''faire ses devoirs'' (fazer lições de casa). Os outros verbos são usados para estado (être), posse (avoir) e movimento (aller).","options":["être","avoir","aller","faire"],"prompt":"Quel verbe est utilisé pour parler d''une action quotidienne ?"},{"answer_index":0,"explanation_pt_br":"O verbo ''être'' é usado para descrever características ou identidade, como ''Marie est une étudiante'' (Marie é uma estudante).","options":["être","avoir","aller","faire"],"prompt":"Dans la phrase ''Marie est une étudiante'', quel verbe est utilisé ?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-564088608d2a', 'fr', 'A1', 'Mes activités quotidiennes', 'Je m''appelle Marie. Je travaille à Paris et j''habite dans un petit appartement. Chaque matin, je me lève à sept heures. Je prends mon café et je mange une tartine. Ensuite, je vais au travail en métro. Au bureau, j''utilise l''ordinateur et je parle avec mes collègues. Le soir, je rentre à la maison. J''écoute de la musique ou je regarde la télévision. Je dîne à huit heures et je me couche à onze heures. Et vous, qu''est-ce que vous faites chaque jour ?', 'Qu''est-ce que Marie fait chaque matin ?', '["Elle se lève à sept heures","Elle va au cinéma","Elle travaille à la maison","Elle dîne à huit heures"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"O texto diz: ''Chaque matin, je me lève à sept heures.'' Portanto, ela se levanta às sete horas.","options":["Elle se lève à sept heures","Elle va au cinéma","Elle travaille à la maison","Elle dîne à huit heures"],"prompt":"Qu''est-ce que Marie fait chaque matin ?"},{"answer_index":2,"explanation_pt_br":"O texto diz: ''je vais au travail en métro.'' Portanto, ela vai de metrô.","options":["En voiture","À pied","En métro","En bus"],"prompt":"Comment Marie va au travail ?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-8ed4991798ab', 'fr', 'A1', 'Posez des questions simples', 'Bonjour ! Aujourd''hui, nous allons apprendre à poser des questions simples en français. C''est très utile pour connaître les gens et pour voyager. Par exemple, vous demandez : « Comment ça va ? » ou « Où est la gare ? ». Pour poser une question, on peut utiliser des mots comme : où, quand, comment, pourquoi, qui, quoi, et combien. On peut aussi changer l''ordre des mots. Normalement, on dit : « Vous avez un chat ? » ou « Avez-vous un chat ? ». Écoutez et répétez. Essayez de demander : « Quel âge avez-vous ? » et « Quelle est votre nationalité ? ». C''est facile et amusant !', 'Quel mot utilisez-vous pour demander un lieu ?', '["Où","Quand","Comment","Pourquoi"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"''Où'' é usado para perguntar sobre lugar, como em ''Où est la gare?'' (Onde fica a estação?).","options":["Où","Quand","Comment","Pourquoi"],"prompt":"Quel mot utilisez-vous pour demander un lieu ?"},{"answer_index":0,"explanation_pt_br":"''Comment ça va ?'' é a forma comum de perguntar ''Como você está?''.","options":["Comment ça va ?","Où es-tu ?","Quel âge as-tu ?","Quelle heure est-il ?"],"prompt":"Comment dit-on ''Como você está?'' en français ?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a1-911c4444d4aa', 'fr', 'A1', 'Les pronoms sujets et les pronoms accentués', 'En français, on utilise les pronoms sujets pour parler de qui fait l''action. Par exemple, « je », « tu », « il », « elle », « nous », « vous », « ils » et « elles ». Après une préposition comme « pour », « avec » ou « à », on utilise les pronoms accentués : « moi », « toi », « lui », « elle », « nous », « vous », « eux » et « elles ». Par exemple, « Ce livre est pour elle. » ou « Tu viens avec moi ? » Les pronoms accentués sont aussi utilisés après « c''est » : « C''est moi ! »', 'Quel pronom utilise-t-on après la préposition « pour » ?', '["je","tu","moi","il"]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"Depois de preposições como ''pour'', usamos os pronomes tônicos: moi, toi, lui, elle, nous, vous, eux, elles. ''Je'' e ''tu'' são pronomes sujeito, não usados depois de preposição.","options":["je","tu","moi","il"],"prompt":"Quel pronom utilise-t-on après la préposition « pour » ?"},{"answer_index":2,"explanation_pt_br":"Depois de ''c''est'', usamos o pronome tônico ''moi''. ''Je'' é sujeito, ''me'' é pronome oblíquo, ''mon'' é possessivo.","options":["je","me","moi","mon"],"prompt":"Complétez la phrase : « C''est ______ qui parle. »"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-105b00765466', 'it', 'A1', 'Quattro verbi importanti', 'Ciao! Oggi impariamo quattro verbi molto importanti in italiano: essere, avere, andare e fare. Questi verbi sono speciali: non seguono le regole normali, quindi dobbiamo memorizzarli. Sono molto usati nella vita di tutti i giorni.

Il verbo "essere" significa "ser" o "estar". Per esempio: "Io sono Marco". Il verbo "avere" significa "ter". Per esempio: "Io ho un libro". Il verbo "andare" significa "ir". Per esempio: "Io vado a casa". Il verbo "fare" significa "fazer". Per esempio: "Io faccio la pizza".

Ora, guardiamo le forme al presente. Con "io": sono, ho, vado, faccio. Con "tu": sei, hai, vai, fai. Con "lui/lei": è, ha, va, fa. Noi: siamo, abbiamo, andiamo, facciamo. Voi: siete, avete, andate, fate. Loro: sono, hanno, vanno, fanno. Pratica ogni giorno e vedrai che è facile!', 'Quale verbo è corretto? Io ___ a scuola.', '["sono","ho","vado","faccio"]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"O verbo ''andare'' (ir) é o correto: ''Io vado a scuola'' significa ''Eu vou à escola''. Os outros verbos não fazem sentido aqui.","options":["sono","ho","vado","faccio"],"prompt":"Quale verbo è corretto? Io ___ a scuola."},{"answer_index":0,"explanation_pt_br":"''Essere'' (ser/estar) é usado para nacionalidade: ''Loro sono italiani'' = ''Eles são italianos''. Os outros verbos não se aplicam.","options":["sono","hanno","vanno","fanno"],"prompt":"Completa: Loro ___ italiani."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-d81d42040952', 'it', 'A1', 'La mia giornata', 'Ciao! Io sono Marco. Ogni giorno mi sveglio alle sette. Poi bevo un caffè e leggo le notizie. Lavoro in un ufficio. Io e i miei colleghi iniziamo a lavorare alle nove. A mezzogiorno, mangiamo insieme una pizza. Nel pomeriggio, finisco il mio lavoro e alle cinque vado a casa. A casa, guardo la TV o leggo un libro. Mia moglie prepara la cena. Noi ceniamo alle otto. Dopo cena, parliamo e ridiamo. Andiamo a letto alle undici. La domenica, invece, facciamo una passeggiata nel parco e beviamo un gelato. Io e la mia famiglia passiamo una bella giornata.', 'A che ora si sveglia Marco?', '["alle sei","alle sette","alle otto","alle nove"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"Marco diz ''mi sveglio alle sette'' (acordo às sete). Portanto, a resposta correta é ''alle sette''.","options":["alle sei","alle sette","alle otto","alle nove"],"prompt":"A che ora si sveglia Marco?"},{"answer_index":2,"explanation_pt_br":"No texto, depois do jantar, eles ''parliamo e ridiamo'' (conversamos e rimos). Portanto, a resposta correta é ''parlano e ridono''.","options":["guardano la TV","leggono un libro","parlano e ridono","fanno una passeggiata"],"prompt":"Che cosa fanno Marco e la moglie dopo cena?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-2cd0f6c657d3', 'it', 'A1', 'Questo e Mio', 'Ciao! Oggi impariamo a usare "questo" e "mio". 

Quando parliamo di una cosa vicina, usiamo "questo" (this). Per esempio: "Questo libro è interessante." Se la cosa è lontana, usiamo "quello" (that). Per esempio: "Quello zaino è pesante." 

Quando vogliamo dire che una cosa è nostra, usiamo "mio" (my) o "mia" per il femminile. Per esempio: "La mia casa è grande." Per il plurale, usiamo "miei" e "mie". 

Ora, prova a rispondere alle domande!', 'Completa: "_____ libro è mio." (This book is mine.)', '["Questo","Quello","Mio","Tuo"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Usamos ''questo'' para indicar algo próximo. ''Quello'' é para algo distante. ''Mio'' e ''tuo'' são possessivos, não demonstrativos.","options":["Questo","Quello","Mio","Tuo"],"prompt":"Completa: \"_____ libro è mio.\" (This book is mine.)"},{"answer_index":0,"explanation_pt_br":"Para feminino singular, usamos ''mia''. ''Mio'' é masculino, ''tuo'' é possessivo de você, e ''questo'' é demonstrativo.","options":["mia","mio","tuo","questo"],"prompt":"Qual è la parola giusta? \"La _____ casa è bella.\" (My house is beautiful.)"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-b86fbbb9061a', 'it', 'A1', 'Posso, voglio, devo: esprimere necessità e desideri', 'In italiano, per esprimere ciò che possiamo fare, ciò che vogliamo e ciò che dobbiamo fare, usiamo tre verbi importanti: **potere**, **volere** e **dovere**. Sono verbi modali, cioè aiutano un altro verbo all''infinito a dare significato alla frase.

**Potere** significa *avere la possibilità o il permesso*. Per esempio: "Io posso parlare italiano." **Volere** esprime un desiderio: "Io voglio un caffè." **Dovere** indica un obbligo: "Io devo studiare."

Ecco la coniugazione al presente indicativo:

- **Potere**: io posso, tu puoi, lui/lei può, noi possiamo, voi potete, loro possono.
- **Volere**: io voglio, tu vuoi, lui/lei vuole, noi vogliamo, voi volete, loro vogliono.
- **Dovere**: io devo, tu devi, lui/lei deve, noi dobbiamo, voi dovete, loro devono.

Quando usi questi verbi con un altro verbo, metti l''altro verbo all''infinito. Per esempio: "Devo andare a casa." Ricorda: la forma negativa si forma con **non** prima del verbo: "Non posso venire."', 'Completa la frase: "Io ______ un gelato." (voglio)', '["posso","voglio","devo","può"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"A frase indica um desejo, por isso usamos ''voglio'' (eu quero). ''Posso'' indica possibilidade, ''devo'' indica obrigação, e ''può'' é a forma de ele/ela.","options":["posso","voglio","devo","può"],"prompt":"Completa la frase: \"Io ______ un gelato.\" (voglio)"},{"answer_index":2,"explanation_pt_br":"A frase expressa uma obrigação no plural, por isso usamos ''devono'' (eles/elas devem). ''Possono'' é possibilidade, ''vogliono'' é desejo, e ''deve'' é singular.","options":["possono","vogliono","devono","deve"],"prompt":"Completa la frase: \"Loro ______ studiare per l''esame.\" (devono)"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-f9e3aa4e128b', 'it', 'A1', 'Preposizioni Semplici e Articolate', 'Le preposizioni semplici sono piccole parole che uniscono le parole in una frase. In italiano, le preposizioni semplici sono: di, a, da, in, con, su, per, tra, fra. Per esempio: "Vado a Roma" (a = direzione), "Il libro è di Maria" (di = possesso).

Quando una preposizione semplice si unisce a un articolo determinativo (il, lo, la, i, gli, le), forma una preposizione articolata. Per esempio: "Vado al cinema" (a + il = al), "Esco dalla casa" (da + la = dalla). Le preposizioni articolate sono molto comuni in italiano e si usano in molte situazioni quotidiane.', 'Quale preposizione articolata si usa per dire "to the cinema"?', '["al","del","nel","sul"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"A preposição articolata \"al\" é a forma correta, pois é a combinação de \"a\" + \"il\" (cinema è maschile singolare).","options":["al","del","nel","sul"],"prompt":"Quale preposizione articolata si usa per dire \"to the cinema\"?"},{"answer_index":0,"explanation_pt_br":"Nesta frase, usamos a preposizione semplice \"di\" para indicar posse, sem contrair com o artigo, pois \"Maria\" é um nome próprio feminino e não leva artigo.","options":["di","del","della","dal"],"prompt":"Completa la frase: \"Questo libro è ___ Maria.\" (Questo libro è di Maria)"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-ed64266b38da', 'it', 'A1', 'Quanto?', 'Quando vai al mercato, chiedi: "Quanto costa?" Questa è una domanda importante. In italiano, usiamo "quanto" per chiedere la quantità o il prezzo. Per esempio, "Quanti euro?" o "Quanto pane?".

Osserva queste frasi:
- Quanto costa il pane? (Che prezzo ha il pane?)
- Quanti libri hai? (Che numero di libri?)
- Quanta acqua bevi? (Che quantità di acqua?)
- Quante mele vuoi? (Che numero di mele?)

Ricorda: "quanto" cambia alla fine: quanto (maschile singolare), quanta (femminile singolare), quanti (maschile plurale), quante (femminile plurale). Usa la forma giusta con il nome.

Ora, rispondi alle domande per praticare.', 'Completa: "______ mele vuoi?" (femminile plurale)', '["Quanto","Quanta","Quanti","Quante"]'::jsonb, 3, '[{"answer_index":3,"explanation_pt_br":"Usamos ''quante'' para substantivos femininos no plural, como ''mele''.","options":["Quanto","Quanta","Quanti","Quante"],"prompt":"Completa: \"______ mele vuoi?\" (femminile plurale)"},{"answer_index":0,"explanation_pt_br":"Para perguntar o preço de algo no masculino singular, usamos ''quanto''.","options":["Quanto","Quanta","Quanti","Quante"],"prompt":"Completa: \"______ costa questo libro?\" (maschile singolare)"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-74b6957106dd', 'it', 'A1', 'Le basi: genere e numero', 'In italiano, i nomi (parole per persone, animali, cose) hanno un genere: maschile o femminile. Di solito, i nomi maschili finiscono in -o e i nomi femminili finiscono in -a. Per esempio: ''libro'' (maschile), ''casa'' (femminile). Inoltre, i nomi hanno un numero: singolare (uno) o plurale (più di uno). Il plurale di un nome maschile finisce in -i, mentre il plurale di un nome femminile finisce in -e. Per esempio: ''libri'' (libri), ''case'' (case). Gli articoli (un, uno, una, il, lo, la, i, gli, le) cambiano con il genere e il numero del nome. ''Un'' o ''uno'' sono per maschile singolare, ''una'' per femminile singolare. ''Il'', ''lo'' sono per maschile singolare, ''la'' per femminile singolare. Per il plurale, ''i'' e ''gli'' per maschile, ''le'' per femminile. È importante scegliere l''articolo giusto per parlare correttamente.', 'Qual è il plurale di ''casa''?', '["case","casi","casas","casa"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"O plural de ''casa'' (feminino) é ''case'', porque femininos terminam em -e no plural.","options":["case","casi","casas","casa"],"prompt":"Qual è il plurale di ''casa''?"},{"answer_index":0,"explanation_pt_br":"''Libro'' é masculino singular, então o artigo definido é ''il''.","options":["il","la","le","i"],"prompt":"Qual è l''articolo determinativo giusto per ''libro'' (singolare)?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-2bdf3eafee37', 'it', 'A1', 'I possessivi e i dimostrativi', 'Ciao! Oggi impariamo i possessivi e i dimostrativi. I possessivi indicano a chi appartiene una cosa. Per esempio: "Il mio libro è qui." I dimostrativi indicano la posizione di una cosa. Per esempio: "Questo libro è qui, quello è là."

In italiano, i possessivi cambiano con il genere e il numero. "Mio" per un maschile singolare, "mia" per un femminile singolare. I dimostrativi: "questo" per vicino, "quello" per lontano. Attenzione alla forma!: "questo" e "quello" cambiano con il nome. Per esempio, "questa macchina" (vicino) e "quella macchina" (lontano).

Ora, leggi gli esempi e fai attenzione!', 'Completa: "______ libro è nuovo."', '["Questo","Quello","Mio","Tuo"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"A forma correta é ''Questo'' porque indica um objeto próximo, e ''libro'' é masculino singular.","options":["Questo","Quello","Mio","Tuo"],"prompt":"Completa: \"______ libro è nuovo.\""},{"answer_index":0,"explanation_pt_br":"A forma correta é ''Questa'' porque indica uma casa próxima, e ''casa'' é feminino singular.","options":["Questa","Quella","Mia","Tua"],"prompt":"Completa: \"______ casa è grande.\""}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-48de55c61154', 'it', 'A1', 'Potere, Volere, Dovere', 'In italiano, i verbi modali sono molto importanti. I tre principali sono: ''potere'' (can), ''volere'' (want), e ''dovere'' (must). Con questi verbi, puoi esprimere possibilità, desiderio e obbligo. Per esempio: "Io posso parlare italiano" (I can speak Italian), "Tu vuoi un caffè?" (Do you want a coffee?), "Noi dobbiamo studiare" (We must study). Questi verbi sono spesso seguiti da un altro verbo all''infinito. Imparare a usarli ti aiuterà a comunicare meglio in italiano.', 'Quale frase usa correttamente ''potere''?', '["Io posso andare al mercato.","Io voglio andare al mercato.","Io devo andare al mercato.","Io sono andare al mercato."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"A frase correta é ''Io posso andare al mercato'', porque ''posso'' é a forma do verbo ''potere'' na primeira pessoa do singular, e é seguido pelo infinitivo ''andare''.","options":["Io posso andare al mercato.","Io voglio andare al mercato.","Io devo andare al mercato.","Io sono andare al mercato."],"prompt":"Quale frase usa correttamente ''potere''?"},{"answer_index":2,"explanation_pt_br":"A frase ''Loro devono mangiare la pizza'' indica obrigação, porque ''devono'' é a forma do verbo ''dovere'' que expressa necessidade ou dever.","options":["Loro vogliono mangiare la pizza.","Loro possono mangiare la pizza.","Loro devono mangiare la pizza.","Loro mangiano la pizza."],"prompt":"Quale frase indica un obbligo?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-389caad6f415', 'it', 'A1', 'Le preposizioni semplici e articolate', 'Le preposizioni semplici sono piccole parole che collegano le parole nella frase: di, a, da, in, con, su, per, tra, fra. Quando una preposizione semplice si unisce a un articolo determinativo (il, lo, la, i, gli, le), forma una preposizione articolata. Per esempio: ''di + il = del'', ''a + il = al'', ''da + il = dal'', ''in + il = nel'', ''su + il = sul''.

Le preposizioni articolate sono molto usate in italiano. Per esempio, diciamo ''Vado al mercato'' (non ''a il mercato'') e ''Il libro è sul tavolo'' (non ''su il tavolo''). Imparare queste forme ti aiuta a parlare in modo naturale. Ecco una lista di alcune preposizioni articolate comuni: del, dello, della, dei, degli, delle; al, allo, alla, ai, agli, alle; dal, dallo, dalla, dai, dagli, dalle; nel, nello, nella, nei, negli, nelle; sul, sullo, sulla, sui, sugli, sulle.

Ora leggi le frasi e rispondi alle domande. Ricorda: usa le preposizioni articolate quando parli di luoghi, tempo, possesso e relazione. Buono studio!', 'Quale frase è corretta?', '["Vado a il cinema.","Vado al cinema.","Vado a lo cinema.","Vado in cinema."]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"A forma correta é ''al cinema'', pois ''a'' + ''il'' = ''al''. As outras opções não existem em italiano.","options":["Vado a il cinema.","Vado al cinema.","Vado a lo cinema.","Vado in cinema."],"prompt":"Quale frase è corretta?"},{"answer_index":2,"explanation_pt_br":"''Sul'' é a forma correta: ''su'' + ''il'' = ''sul''. As outras não são usadas com ''tavolo'' nesse contexto.","options":["del","dal","sul","nel"],"prompt":"Quale preposizione articola si usa con ''tavolo''?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-5928e5f59c78', 'it', 'A1', 'Mi Piace: Esprimere Gusti e Preferenze', 'Ciao! Oggi impariamo a dire cosa ci piace. In italiano, usiamo "mi piace" per una cosa e "mi piacciono" per più cose. Per esempio: "Mi piace la pizza" (una cosa) e "Mi piacciono le pizze" (più cose).

Ascolta: "Mi piace il caffè" e "Mi piacciono i libri". Attenzione! Usiamo "mi piace" anche con un verbo: "Mi piace leggere".

Ora, parla di te. Usa "mi piace" o "mi piacciono". Ricorda: "mi piace" con una cosa o un''azione, "mi piacciono" con più cose.', 'Completa: A me ___ il gelato.', '["piace","piacciono","piaci","piaccio"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Usamos \"piace\" para uma coisa (singular). \"Il gelato\" é singular, então ''piace''.","options":["piace","piacciono","piaci","piaccio"],"prompt":"Completa: A me ___ il gelato."},{"answer_index":1,"explanation_pt_br":"Usamos \"piacciono\" para várias coisas (plural). \"I film\" é plural, então ''piacciono''.","options":["piace","piacciono","piaci","piaciono"],"prompt":"Completa: A me ___ i film."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-a2c265952b16', 'it', 'A1', 'Quanto c''è?', 'In italiano, usiamo "quanto" e "quanti" per chiedere la quantità. "Quanto" si usa con i nomi non numerabili (es. pane, acqua), mentre "quanti" si usa con i nomi numerabili plurali (es. libri, amici).

Per rispondere, usiamo "molto/a" per una grande quantità e "poco/a" per una piccola quantità. Per esempio: "Quanto pane c''è? C''è molto pane." oppure "Quanti libri hai? Ho pochi libri.".

Osserva gli esempi: "Quanta pasta vuoi?" (non numerabile) e "Quanti studenti ci sono?" (numerabile). Ricorda: "quanto" cambia in base al genere e al numero del nome.', 'Scegli la domanda corretta per chiedere la quantità di acqua.', '["Quanti acqua c''è?","Quanto acqua c''è?","Quanta acqua c''è?","Quante acqua c''è?"]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"Usamos \"quanta\" porque \"acqua\" é um substantivo feminino singular. \"Quanti\" e \"quante\" são para plural, e \"quanto\" é masculino.","options":["Quanti acqua c''è?","Quanto acqua c''è?","Quanta acqua c''è?","Quante acqua c''è?"],"prompt":"Scegli la domanda corretta per chiedere la quantità di acqua."},{"answer_index":3,"explanation_pt_br":"Usamos \"molti\" porque \"amici\" é masculino plural. \"Pochi\" seria para pequena quantidade, e \"molto\" é singular.","options":["poco","pochi","molto","molti"],"prompt":"Completa: \"Oggi ho ______ amici a casa.\" (grande quantità)"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-33475ae4cf35', 'it', 'A1', 'Articoli e Nomi al Ristorante', 'In italiano, i nomi (parole per persone, animali, cose) hanno un genere: maschile o femminile. Per esempio, "libro" è maschile e "casa" è femminile. Anche i numeri sono importanti: un nome può essere singolare (uno) o plurale (più di uno). Gli articoli (il, la, un, una) cambiano con il genere e il numero del nome.

Al ristorante, è utile conoscere alcuni nomi di cibo. "Pizza" è femminile, quindi diciamo "la pizza" e "una pizza". "Vino" è maschile, quindi diciamo "il vino" e "un vino". Imparare questi piccoli dettagli aiuta a parlare meglio in italiano.

Ora, guardiamo due esempi:
1. "Vorrei una pizza." (Pizza è femminile, quindi usiamo "una".)
2. "Vorrei un vino." (Vino è maschile, quindi usiamo "un".)

Ricorda: con "il" (determinativo) e "un" (indeterminativo) usiamo nomi maschili; con "la" e "una" usiamo nomi femminili. Per il plurale, "i" e "gli" per maschile, "le" per femminile.', 'Quale articolo si usa con il nome ''pizza''?', '["il","la","un","i"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"Pizza é um substantivo feminino, então usamos o artigo definido feminino singular ''la''.","options":["il","la","un","i"],"prompt":"Quale articolo si usa con il nome ''pizza''?"},{"answer_index":2,"explanation_pt_br":"Vino é um substantivo masculino, então usamos o artigo indefinido masculino singular ''un''.","options":["una","la","un","le"],"prompt":"Quale articolo si usa con il nome ''vino''?"}]'::jsonb, 0, true)
