insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-925b8f983583', 'it', 'A1', 'La Mia Giornata', 'Ciao! Mi chiamo Marco. Ogni giorno mi sveglio alle sette. Poi faccio colazione con caffè e pane. Lavoro in un ufficio. Il mio amico Luca viene a pranzo con me. Nel pomeriggio, lui va in palestra, ma io guardo la TV. La sera, noi usciamo con gli amici. Anche tu fai queste cose?', 'Quando si sveglia Marco?', '["alle sette","alle otto","alle nove","alle dieci"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"O texto diz: ''Ogni giorno mi sveglio alle sette.''","options":["alle sette","alle otto","alle nove","alle dieci"],"prompt":"Quando si sveglia Marco?"},{"answer_index":1,"explanation_pt_br":"O texto diz: ''Il mio amico Luca viene a pranzo con me.''","options":["lavora","viene","guarda la TV","esce"],"prompt":"Cosa fa Marco con Luca a pranzo?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-c7322e2dff04', 'it', 'A1', 'Questo e Quello: Come Indicare le Cose', 'Quando parliamo, vogliamo indicare le cose. Usiamo "questo" e "quello" per dire se una cosa è vicina o lontana. Questo aiuta a capire meglio cosa vogliamo.

Per esempio, se un libro è vicino a me, dico: "Questo libro è interessante." Se un libro è lontano, dico: "Quello libro è interessante." In italiano, "questo" è per cose vicine e "quello" per cose lontane.

Ricorda: "questo" e "quello" cambiano con il nome. Con un nome maschile singolare usiamo "questo" e "quello". Con un nome femminile singolare usiamo "questa" e "quella". Per il plurale, usiamo "questi" e "quelli" per maschile, "queste" e "quelle" per femminile. Ad esempio: "Questa casa è bella" (vicina) e "Quella casa è bella" (lontana).', 'Complete: ______ libro è interessante. (Il libro è vicino a me.)', '["Quello","Questo","Quella","Questi"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"Usamos ''questo'' para objetos próximos, masculino singular.","options":["Quello","Questo","Quella","Questi"],"prompt":"Complete: ______ libro è interessante. (Il libro è vicino a me.)"},{"answer_index":2,"explanation_pt_br":"Usamos ''quella'' para objetos distantes, feminino singular.","options":["Questa","Quello","Quella","Questo"],"prompt":"Complete: ______ casa è lontana."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-e71b72d429e6', 'it', 'A1', 'Potere, Volere, Dovere', 'Ciao! Oggi impariamo tre verbi molto importanti in italiano: **potere**, **volere** e **dovere**. Questi verbi sono modali, cioè aiutano altri verbi. Per esempio: "Io posso parlare italiano" (I can speak Italian). "Tu vuoi mangiare una pizza" (You want to eat a pizza). "Lei deve studiare" (She must study).

Usiamo **potere** per esprimere capacità o permesso. **Volere** per desiderio. **Dovere** per obbligo o necessità. Sono verbi irregolari, ma con la pratica diventano facili.

Quando usi questi verbi, il secondo verbo è all''infinito. Per esempio: "Devo andare a casa" (I must go home). Attenzione alla posizione: il verbo modale si coniuga, l''infinito rimane invariato. Buono studio!', 'Quale verbo usi per esprimere una capacità?', '["potere","volere","dovere","essere"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Usiamo ''potere'' para expressar capacidade ou permissão. ''Volere'' é para desejo, ''dovere'' para obrigação.","options":["potere","volere","dovere","essere"],"prompt":"Quale verbo usi per esprimere una capacità?"},{"answer_index":0,"explanation_pt_br":"''Voglio mangiare'' significa ''Eu quero comer''. ''Posso'' é ''posso'', ''Devo'' é ''devo'', e ''Sono'' é ''sou/estou''.","options":["Voglio mangiare","Posso mangiare","Devo mangiare","Sono mangiare"],"prompt":"Come si dice ''I want to eat''?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-44732a3a2b34', 'it', 'A1', 'La città e le preposizioni', 'Ciao! Oggi parliamo della città e delle preposizioni semplici e articolate. In italiano, usiamo le preposizioni per dire dove sono le cose. Per esempio: "Il libro è sul tavolo". "Sul" è una preposizione articolata: su + il = sul. Le preposizioni semplici sono: di, a, da, in, con, su, per, tra, fra. Quando le uniamo con gli articoli (il, lo, la, i, gli, le), formiamo le preposizioni articolate. Ecco alcuni esempi:', 'Quale preposizione articulata usiamo per dire "on the table"?', '["sul","nel","al","dal"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"A forma correta é ''sul'', que é a união de ''su'' + ''il''.","options":["sul","nel","al","dal"],"prompt":"Quale preposizione articulata usiamo per dire \"on the table\"?"},{"answer_index":2,"explanation_pt_br":"A forma correta é ''nel'', que é a união de ''in'' + ''il''.","options":["nella","nello","nel","nei"],"prompt":"Quale preposizione articulata significa \"in the house\"?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-3fd689573a87', 'it', 'A1', 'Mi piace e non mi piace', 'In italiano, per esprimere i tuoi gusti, usi il verbo "piacere". Attenzione: non si dice "io piace", ma "mi piace" quando ti piace una cosa singola. Se ti piacciono più cose, usi "mi piacciono". Per esempio: "Mi piace la pizza" e "Mi piacciono le mele". Con i verbi all''infinito, usi sempre "mi piace": "Mi piace leggere". Per dire che non ti piace, metti "non" prima: "Non mi piace il calcio". Per chiedere a un amico, usi "Ti piace" o "Ti piacciono". E per parlare di un''altra persona, "Gli piace" (a lui) o "Le piace" (a lei). Ecco una conversazione tra Anna e Marco:

Anna: Ciao Marco, ti piace il gelato?
Marco: Sì, mi piace molto. Mi piacciono anche i biscotti.
Anna: E ti piace nuotare?
Marco: No, non mi piace nuotare. A mia sorella piace, invece!

Ora prova a fare le domande!', 'Cosa usi per dire che ti piace una cosa singola?', '["mi piace","mi piacciono","ti piace","gli piace"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Em italiano, para uma coisa singular, usamos ''mi piace''. Para várias coisas, usamos ''mi piacciono''.","options":["mi piace","mi piacciono","ti piace","gli piace"],"prompt":"Cosa usi per dire che ti piace una cosa singola?"},{"answer_index":1,"explanation_pt_br":"Quando o objeto é plural, usamos ''mi piacciono'' e o artigo e substantivo no plural: ''i libri''.","options":["Mi piace i libri.","Mi piacciono i libri.","Mi piacciono il libro.","Mi piace il libri."],"prompt":"Quale frase é correta?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-aec0a4457d9a', 'it', 'A1', 'Quanti? Quanto?', 'Ciao! Oggi impariamo a parlare di quantità. Quando vogliamo sapere "quanto?" o "quanti?", usiamo le parole "quanto" e "quanti". "Quanto" è per cose che non si contano, come acqua o pane. "Quanti" è per cose che si contano, come libri o mele.

Per esempio: "Quanto caffè bevi?" e "Quanti libri hai?" Sono domande utili al bar o al mercato. Quando rispondi, puoi dire "un po''", "molto", "due", "tre" e così via.

Ora prova a fare domande e rispondere in italiano. È facile e utile!', 'Quale parola usi per chiedere la quantità di acqua?', '["Quanto","Quanti","Quanta","Quante"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Usamos \"quanto\" para substantivos masculinos incontáveis, como \"acqua\" (água). \"Quanta\" é feminino, mas \"acqua\" é feminina, então seria \"quanta acqua\". Aqui, a opção correta é \"Quanto\" porque a pergunta é sobre a palavra em geral, não gênero.","options":["Quanto","Quanti","Quanta","Quante"],"prompt":"Quale parola usi per chiedere la quantità di acqua?"},{"answer_index":2,"explanation_pt_br":"\"Mele\" (maçãs) é um substantivo feminino plural, então usamos \"quante\" para perguntar quantidade contável no plural feminino.","options":["Quanto mele?","Quanti mele?","Quante mele?","Quanta mele?"],"prompt":"Come chiedi il numero di mele?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-b6e73a5918cd', 'it', 'A1', 'Il genere e il numero dei nomi', 'In italiano, i nomi hanno un genere (maschile o femminile) e un numero (singolare o plurale). Questo è molto importante per usare gli articoli giusti.

Osserva questi esempi:
- "un libro" (maschile singolare)
- "due libri" (maschile plurale)
- "una casa" (femminile singolare)
- "due case" (femminile plurale)

Quando il nome finisce in -o, di solito è maschile. Quando finisce in -a, di solito è femminile. Al plurale, -o diventa -i e -a diventa -e.

Attenzione: ci sono eccezioni! Per esempio, "il problema" è maschile anche se finisce in -a. Ma non preoccuparti: con la pratica, diventa naturale.

Ecco una regola semplice:
- Maschile singolare: il / un
- Maschile plurale: i / dei
- Femminile singolare: la / una
- Femminile plurale: le / delle

Ora prova a rispondere alle domande!', 'Completa la frase con l''articolo giusto: "... libro è nuovo."', '["Il","La","Un","Una"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"A palavra ''libro'' é masculina singular, então usamos o artigo definido ''il''.","options":["Il","La","Un","Una"],"prompt":"Completa la frase con l''articolo giusto: \"... libro è nuovo.\""},{"answer_index":0,"explanation_pt_br":"A palavra ''casa'' é feminina e no plural fica ''case'', portanto o artigo definido plural feminino é ''le''.","options":["Le","La","I","Gli"],"prompt":"Scegli la forma corretta al plurale: \"... casa sono grandi.\""}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-4d6271eed603', 'it', 'A1', 'Il presente dei verbi regolari e irregolari frequenti', 'Ciao! Oggi impariamo il presente dei verbi in italiano. Il presente si usa per azioni che succedono adesso o sempre. Per esempio, “Maria lavora in un ufficio” e “Noi mangiamo la pizza ogni venerdì”. I verbi regolari hanno tre gruppi: -ARE, -ERE e -IRE. Per esempio, “parlare” (to speak) diventa: io parlo, tu parli, lui/lei parla, noi parliamo, voi parlate, loro parlano. I verbi irregolari più frequenti sono “essere”, “avere”, “fare” e “andare”. “Essere” è molto importante: io sono, tu sei, lui/lei è, noi siamo, voi siete, loro sono. “Avere”: io ho, tu hai, lui/lei ha, noi abbiamo, voi avete, loro hanno. “Fare” (to do): io faccio, tu fai, lui/lei fa, noi facciamo, voi fate, loro fanno. “Andare” (to go): io vado, tu vai, lui/lei va, noi andiamo, voi andate, loro vanno. Ricorda: con “io” spesso usiamo “io” ma non è obbligatorio. Per esempio, “Sono brasiliano” o “Io sono brasiliano”. In italiano non usiamo sempre il soggetto. Oggi pratichiamo con due domande!', 'Qual è la forma corretta del verbo “andare” con “io”?', '["io vado","io vai","io va","io ando"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"A forma correta do presente do verbo ''andare'' com ''io'' é ''vado''. As outras opções são de outras pessoas ou formas incorretas: ''vai'' é para ''tu'', ''va'' é para ''lui/lei'', ''ando'' não existe.","options":["io vado","io vai","io va","io ando"],"prompt":"Qual è la forma corretta del verbo “andare” con “io”?"},{"answer_index":0,"explanation_pt_br":"A forma correta do verbo ''essere'' para ''loro'' é ''sono''. ''Siamo'' é para ''noi'', ''è'' para ''lui/lei'', ''sei'' para ''tu''.","options":["sono","siamo","è","sei"],"prompt":"Completa: “Loro ______ italiani.” (essere)"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-8b0733518a74', 'it', 'A1', 'Non e Domande: Imparare a Negare e Chiedere', 'Ciao! Oggi impariamo a dire "non" e a fare domande in italiano. Questo è molto utile ogni giorno.

Per negare una frase, mettiamo "non" prima del verbo. Per esempio: "Io parlo italiano" diventa "Io non parlo italiano". Facile, no?

Per fare domande, possiamo usare "chi?", "che cosa?", "dove?", "quando?", "perché?". Oppure, possiamo alzare la voce alla fine della frase. Per esempio: "Tu parli italiano?" è una domanda con la voce. "Dove abiti?" è una domanda con una parola interrogativa.

Ora leggiamo un piccolo dialogo tra Anna e Marco.

Anna: Ciao Marco! Come stai?
Marco: Ciao Anna! Sto bene, grazie. E tu? Non sto molto bene oggi.
Anna: Perché? Che cosa hai?
Marco: Ho mal di testa. Non ho dormito bene. E tu, dove vai?
Anna: Vado al mercato. Non compro niente, solo guardo. Vuoi venire?
Marco: Sì, volentieri! Ma non posso camminare veloce.
Anna: Non importa. Andiamo piano.

Adesso rispondi alle domande.
', 'Perché Marco non sta bene?', '["Ha mal di testa.","Ha mal di pancia.","Ha mal di denti.","Ha fame."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"No diálogo, Marco diz ''Ho mal di testa'', que significa ''Estou com dor de cabeça''.","options":["Ha mal di testa.","Ha mal di pancia.","Ha mal di denti.","Ha fame."],"prompt":"Perché Marco non sta bene?"},{"answer_index":2,"explanation_pt_br":"Anna diz ''Non compro niente, solo guardo'', ou seja, ela não compra nada, apenas olha.","options":["Compra frutta.","Compra verdura.","Non compra niente.","Compra pane."],"prompt":"Che cosa compra Anna al mercato?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-d78daffb90fa', 'it', 'A1', 'Potere, Volere, Dovere: Usos Básicos', 'In italiano usiamo spesso tre verbi speciali per esprimere capacità, desiderio e necessità: potere (posso), volere (voglio) e dovere (devo). Questi verbi sono irregolari e molto importanti. Per esempio, puoi dire "Posso andare?" per chiedere permesso, oppure "Voglio un caffè" per esprimere un desiderio. Inoltre, "Devo studiare" indica un obbligo. Questi verbi sono di solito seguiti da un infinito, come "andare" o "studiare".

Facciamo pratica con alcuni esempi. Immagina di essere in un bar. Potresti dire "Posso avere un caffè?" per chiedere educatamente. Se vuoi un cornetto, dici "Voglio un cornetto." Se devi andare al lavoro, dici "Devo andare al lavoro." Ricorda che questi verbi cambiano forma: io posso, tu puoi, lui/lei può; io voglio, tu vuoi, lui/lei vuole; io devo, tu devi, lui/lei deve.

Ora proviamo a usarli con altri verbi. Per esempio, "Posso parlare italiano?" (riesco a parlare italiano?), "Vuoi mangiare?" (hai voglia di mangiare?), "Devo comprare il pane." (ho bisogno di comprare il pane).', 'Qual é a forma correta de ''potere'' para ''io''?', '["posso","puoi","può","possiamo"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"A forma correta de ''potere'' para ''io'' é ''posso''. As outras opções são para outras pessoas: ''puoi'' (tu), ''può'' (lui/lei), ''possiamo'' (noi).","options":["posso","puoi","può","possiamo"],"prompt":"Qual é a forma correta de ''potere'' para ''io''?"},{"answer_index":2,"explanation_pt_br":"O verbo ''dovere'' expressa necessidade ou obrigação, como em ''devo studiare'' (devo estudar).","options":["potere","volere","dovere","avere"],"prompt":"Qual verbo expressa necessidade?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-3bb44b3e7b86', 'it', 'A1', 'Preposizioni semplici e articolate', 'Le preposizioni sono parole piccole ma molto importanti in italiano. Uniscono le parole e le frasi. Per esempio: "Vado a Roma", "Il libro è di Maria", "Parlo con Paolo". Oggi impariamo le preposizioni semplici: di, a, da, in, con, su, per, tra, fra.

Quando una preposizione semplice si unisce a un articolo determinativo (il, lo, la, i, gli, le), forma una preposizione articolata. Per esempio: "il libro è sul tavolo" (su + il), "vado al cinema" (a + il), "esco dalla scuola" (da + la).

Osserva come si formano: di + il = del, di + lo = dello, di + la = della, di + i = dei, di + gli = degli, di + le = delle. A + il = al, a + lo = allo, a + la = alla, a + i = ai, a + gli = agli, a + le = alle. Da + il = dal, da + lo = dallo, da + la = dalla, da + i = dai, da + gli = dagli, da + le = dalle. In + il = nel, in + lo = nello, in + la = nella, in + i = nei, in + gli = negli, in + le = nelle. Con + il = col, con + lo = collo, con + la = colla, con + i = coi, con + gli = cogli, con + le = colle. Su + il = sul, su + lo = sullo, su + la = sulla, su + i = sui, su + gli = sugli, su + le = sulle.

Le preposizioni articolate sono molto usate. Pratica con gli esercizi!', 'Quale preposizione articolata è corretta? (completa la frase: "Il libro è ___ tavolo.")', '["al","del","sul","nel"]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"A frase indica posição sobre a mesa. ''Sul'' = su + il, que significa ''sobre o''.","options":["al","del","sul","nel"],"prompt":"Quale preposizione articolata è corretta? (completa la frase: \"Il libro è ___ tavolo.\")"},{"answer_index":0,"explanation_pt_br":"Vamos ao cinema. ''Al'' = a + il, que significa ''ao''.","options":["al","dal","nel","sul"],"prompt":"Quale preposizione articolata è corretta? (completa la frase: \"Vado ___ cinema.\")"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-c2d46a028692', 'it', 'A1', 'Mi piace la pizza!', 'Ciao! Oggi parliamo di "mi piace". In italiano, quando ti piace qualcosa, usi "mi piace". Ad esempio: "Mi piace la pizza". Se ti piace tanto, puoi dire "Mi piace molto". Se non ti piace, dici "Non mi piace". Per chiedere a un amico, usi "Ti piace?". Per esempio: "Ti piace il caffè?" Per parlare di più cose, usi "mi piacciono". Ad esempio: "Mi piacciono i dolci". Ma per ora, impariamo "mi piace" e "non mi piace".', 'Guarda le parole: pizza, caffè, musica, gelato. Quale frase è corretta?', '["Mi piace la musica.","Mi piace il pizza.","Mi piace il caffè.","Mi piace i gelato."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"''Musica'' é palavra feminina, então usamos ''la'' antes. As outras têm artigo errado: ''il'' para ''pizza'' seria ''la pizza'', ''il caffè'' está correto, mas a de índice 0 é correta também.","options":["Mi piace la musica.","Mi piace il pizza.","Mi piace il caffè.","Mi piace i gelato."],"prompt":"Guarda le parole: pizza, caffè, musica, gelato. Quale frase è corretta?"},{"answer_index":0,"explanation_pt_br":"Quando alguém pergunta ''Ti piace?'', respondemos com ''Mi piace'' (eu gosto). As outras opções estão incorretas.","options":["Sì, mi piace.","Sì, ti piace.","No, ti piace.","Sì, mi piace il."],"prompt":"Pensa: ''Ti piace il calcio?'' O que você responde?"}]'::jsonb, 0, true)
