insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-d0f612182dc0', 'it', 'A1', 'La routine di Marco', 'Marco è un impiegato a Roma. Ogni giorno si sveglia alle sette e beve un caffè. Poi va al lavoro in autobus. Lavora dalle nove alle cinque. A pranzo, mangia un panino al bar vicino all''ufficio. Dopo il lavoro, Marco spesso va in palestra. A casa, prepara la cena e guarda un po'' di televisione. Nel fine settimana, esce con gli amici o fa una passeggiata al parco. Marco ama la sua routine, ma a volte vuole fare qualcosa di diverso.

Al mattino beve un caffè. Al pomeriggio, di solito, beve un tè e mangia un biscotto. La sera beve un bicchiere di vino con la cena. Ogni giorno, Marco fa molte cose: lavora, cucina, legge, e dorme. Le sue azioni sono semplici, ma fanno parte della sua vita.

Marco è contento della sua vita. Ha una famiglia e degli amici. Lavora sodo, ma trova anche tempo per il riposo. La vita è bella.', 'Che cosa fa Marco ogni mattina?', '["Va al lavoro in macchina","Beve un caffè","Fa colazione con gli amici","Prepara la cena"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"Il testo dice: ''Ogni giorno si sveglia alle sette e beve un caffè.'' Quindi, Marco beve un caffè ogni mattina.","options":["Va al lavoro in macchina","Beve un caffè","Fa colazione con gli amici","Prepara la cena"],"prompt":"Che cosa fa Marco ogni mattina?"},{"answer_index":2,"explanation_pt_br":"Il testo dice: ''A pranzo, mangia un panino al bar vicino all''ufficio.'' Quindi, Marco mangia al bar vicino all''ufficio.","options":["A casa","Al ristorante","Al bar vicino all''ufficio","Al parco"],"prompt":"Dove mangia Marco a pranzo?"}]'::jsonb, 0, true)
