insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-4e164daeee15', 'it', 'A1', 'Che cos''è JavaScript?', 'JavaScript è un linguaggio di programmazione molto usato. I programmatori lo usano per rendere le pagine web interattive. Quando apri un sito web, JavaScript può cambiare il contenuto, mostrare messaggi o creare effetti speciali. È diverso da HTML, che serve per la struttura della pagina. Con JavaScript, il browser esegue le istruzioni e la pagina diventa dinamica.

JavaScript si può usare anche per creare giochi e applicazioni. Ogni giorno, molte persone usano JavaScript senza saperlo. È un linguaggio per tutti, non solo per esperti. Con un po'' di pratica, puoi imparare a usarlo anche tu.

In questa lezione, parliamo di JavaScript e di come funziona nel web.', 'Perché usiamo JavaScript?', '["Per rendere le pagine web interattive","Per creare immagini","Per scrivere testi","Per ascoltare musica"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"JavaScript é usado para tornar as páginas web interativas, como mostrado no texto. As outras opções não são funções do JavaScript.","options":["Per rendere le pagine web interattive","Per creare immagini","Per scrivere testi","Per ascoltare musica"],"prompt":"Perché usiamo JavaScript?"},{"answer_index":1,"explanation_pt_br":"O texto explica que JavaScript é diferente de HTML: HTML é para a estrutura da página, enquanto JavaScript torna a página interativa.","options":["Sì, sono la stessa cosa","No, JavaScript è diverso da HTML","Sì, ma solo per i principianti","No, HTML è più difficile"],"prompt":"JavaScript è uguale a HTML?"}]'::jsonb, 0, true)
