insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-a7ca8d2d6676', 'it', 'A1', 'Non capisco: Negazioni e Domande in Italiano', 'Ciao! Oggi impariamo a fare domande e a dire no in italiano. Usiamo "non" per fare frasi negative. Per esempio: "Io non parlo inglese". Per fare domande, alziamo la voce alla fine della frase. Oppure usiamo parole come "Chi?", "Che cosa?", "Dove?", "Quando?", "Perché?", "Come?". 

Ecco un dialogo: Marco chiede a Anna: "Dove lavori?" Anna risponde: "Lavoro in un ufficio." Marco dice: "Non capisco. Che cosa fai?" Anna: "Sono un''ingegnere. E tu? Lavori?". Marco: "No, non lavoro. Studio italiano.". 

Ricorda: "Non" viene prima del verbo. Le domande con "chi", "che cosa", "dove" hanno una intonazione speciale. Con "sì" o "no" possiamo rispondere alle domande. Per esempio, "Parli italiano?" - "Sì, parlo italiano." oppure "No, non parlo italiano.". 

Ora, esercitiamoci!', 'Quale frase è negativa?', '["Io parlo italiano.","Io non parlo inglese.","Dove lavori?","Che cosa fai?"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"A frase com ''non'' antes do verbo é negativa. ''Io non parlo inglese.'' significa ''Eu não falo inglês.''","options":["Io parlo italiano.","Io non parlo inglese.","Dove lavori?","Che cosa fai?"],"prompt":"Quale frase è negativa?"},{"answer_index":2,"explanation_pt_br":"''Dove?'' significa ''Onde?'' e é usada para perguntar sobre lugar.","options":["Chi?","Che cosa?","Dove?","Quando?"],"prompt":"Quale parola si usa per fare una domanda sul luogo?"}]'::jsonb, 0, true)
