insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-755c59b58c62', 'it', 'A1', 'Questo e Quello: Cose Vicine e Lontane', 'Ciao! Oggi impariamo due parole molto utili in italiano: "questo" e "quello". Usiamo "questo" per cose vicine a noi, e "quello" per cose lontane. Per esempio, se hai un libro in mano, dici "questo libro". Se il libro è sullo scaffale lontano, dici "quel libro" (forma breve di "quello").

Osserva: "questo" ha forme diverse: "questo" (maschile singolare), "questa" (femminile singolare), "questi" (maschile plurale), "queste" (femminile plurale). "Quello" cambia in "quel" davanti a consonante, "quello" davanti a s+consonante o z, "quella" (femminile singolare), "quei" (maschile plurale), "quelle" (femminile plurale). Non preoccuparti, con la pratica diventa facile!

Guarda le frasi: "Questa mela è buona" (vicina). "Quella mela è lontana" (lontana). "Questi fiori sono belli" (vicini). "Quei fiori sono gialli" (lontani). Ora prova a rispondere alle domande!', 'Completa: ___ libro è sul tavolo. (vicino a me)', '["Questo","Quello","Quel","Questa"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Usamos ''questo'' para coisas perto de nós. ''Quello'' é para longe, ''quel'' é a forma abreviada de ''quello'' antes de consoante, e ''questa'' é feminino.","options":["Questo","Quello","Quel","Questa"],"prompt":"Completa: ___ libro è sul tavolo. (vicino a me)"},{"answer_index":0,"explanation_pt_br":"Para uma caneta (feminina) longe, usamos ''quella''. ''Questa'' é para perto; ''quel'' é forma masculina; ''quello'' é usado antes de s+consoante ou z.","options":["Quella penna è rossa (lontana).","Questa penna è rossa (lontana).","Quel penna è rossa (lontana).","Quello penna è rossa (lontana)."],"prompt":"Scegli la frase corretta:"}]'::jsonb, 0, true)
