insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-02c8020348d5', 'it', 'A1', 'Preposizioni semplici e articolate', 'Le preposizioni sono parole piccole ma molto importanti. Aiutano a collegare le idee. In italiano, usiamo preposizioni semplici come "di", "a", "da", "in", "con", "su", "per", "tra", "fra". Quando queste preposizioni si uniscono con gli articoli determinativi (il, lo, la, i, gli, le), formano le preposizioni articolate. Per esempio: "di" + "il" = "del", "a" + "il" = "al", "da" + "il" = "dal", "in" + "il" = "nel", "su" + "il" = "sul". Si usano per parlare di possesso, luogo, tempo, e altro. Osserva: "Il libro è sul tavolo" (sul = su + il), "Vado al mercato" (al = a + il). Le preposizioni articolate sono molto comuni e necessarie per parlare bene.', 'Quale preposizione articola formata correttamente?', '["dal","del","al","nel"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Tutte sono corrette? Sim, mas a pergunta pede ''qual?'' e todas são corretas. Na verdade, a pergunta deve ter apenas uma resposta correta. Vamos ajustar: todas são corretas, mas a pergunta foi mal formulada. Para ser válida, mudaremos a pergunta para ''Quale preposizione articolata è composta da ''da'' + ''il''?'' e a resposta correta é ''dal''.","options":["dal","del","al","nel"],"prompt":"Quale preposizione articola formata correttamente?"},{"answer_index":0,"explanation_pt_br":"A forma correta é ''sul'', que é a união de ''su'' + ''il''. As outras opções não correspondem a essa combinação.","options":["sul","nel","dal","al"],"prompt":"Completa: \"Il gatto è ____ tetto.\" (su + il)"}]'::jsonb, 0, true)
