insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-0bd3f2f485e8', 'it', 'A1', 'Mi piace!', 'Ciao! Oggi impariamo a dire cosa ci piace. In italiano, usiamo “mi piace” per una cosa e “mi piacciono” per più cose. Per esempio: “Mi piace la pizza” e “Mi piacciono gli spaghetti”. Attenzione: dopo “mi piace” usiamo il verbo all''infinito, come “Mi piace leggere”.

Quando parliamo con gli amici, possiamo dire “Ti piace il calcio?” per chiedere cosa piace a loro. E per parlare di altre persone, usiamo “Gli piace” o “Le piace”. Per esempio: “A Marco piace la musica” oppure “A Maria piacciono i film”.

Ora, facciamo un piccolo esercizio. Rispondi alle domande e pratica!', 'Cosa dici per una cosa che ti piace?', '["Mi piacciono","Mi piace","Ti piace","Gli piace"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"Para uma coisa que você gosta, usamos ''mi piace''. ''Mi piacciono'' é para várias coisas.","options":["Mi piacciono","Mi piace","Ti piace","Gli piace"],"prompt":"Cosa dici per una cosa che ti piace?"},{"answer_index":0,"explanation_pt_br":"Para dizer que o Marco gosta de pizza, usamos ''A Marco piace la pizza'' porque ''pizza'' é singular.","options":["A Marco piace la pizza.","A Marco piacciono la pizza.","Marco mi piace la pizza.","Ti piace la pizza."],"prompt":"Come si dice quando a Marco piace la pizza?"}]'::jsonb, 0, true)
