insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a1-9015c4bba11d', 'it', 'A1', 'Quanto pane? Quanti caffè?', 'Oggi impariamo a parlare di quantità. In italiano, usiamo "quanto" e "quanti" per chiedere la quantità. "Quanto" si usa con i nomi singolari maschili (es. pane, formaggio) e "quanti" con i nomi plurali maschili (es. caffè, bicchieri). Per esempio: "Quanto pane vuoi?" (How much bread do you want?) e "Quanti caffè prendi?" (How many coffees do you have?). Ricorda: in italiano, i nomi come "caffè" non cambiano al plurale. "Quanto" e "quanti" sono parole importanti per fare la spesa o ordinare al bar.

Quando rispondiamo, usiamo "molto" o "molti" per dire "a lot of". "Molto" si usa con i nomi singolari (es. "molto pane") e "molti" con i nomi plurali (es. "molti caffè"). Per esempio: "Prendo molto pane" e "Bevo molti caffè". Anche "poco" e "pochi" significano "a little" o "few". "Poco" per singolare (es. "poco zucchero") e "pochi" per plurale (es. "pochi biscotti").

Ora, facciamo pratica! Leggi le domande e scegli la risposta giusta.', 'Completa: "Quanti ______ prendi?" (How many coffees do you have?)', '["caffè","pane","formaggio","zucchero"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Usamos \"quanti\" com substantivos masculinos no plural. \"Caffè\" é invariável no plural, mas é contável, então \"quanti caffè\" está correto. As outras opções são singulares ou não contáveis.","options":["caffè","pane","formaggio","zucchero"],"prompt":"Completa: \"Quanti ______ prendi?\" (How many coffees do you have?)"},{"answer_index":2,"explanation_pt_br":"Usamos \"quanto\" com substantivos singulares e não contáveis, como \"pane\". As outras opções são plurais ou contáveis.","options":["biscotti","caffè","pane","bicchieri"],"prompt":"Completa: \"Quanto ______ vuoi?\" (How much bread do you want?)"}]'::jsonb, 0, true)
